do $elaz_import$
declare
  p jsonb := $elaz_content${"course":{"key":"ai-video","title":"Ролики с ИИ: от идеи до MP4","subtitle":"20 уроков: инструменты, визуал, озвучка, сборка и следующие выпуски","description":"Практический курс Elaz Ed о создании коротких роликов с агентом. Шесть модулей: подключаем инструменты, готовим проект, выстраиваем визуал, собираем первый выпуск, повторяем процесс и находим идеи.\n\nВ каждом уроке — объяснение, задание и проверка результата. Учебный проект: короткий ролик о выборе телефона под разные задачи. Можно использовать свою тему.\n\nВводный урок «Как агент собирает ролик» открыт всем. Доступ к остальным урокам выдаётся через заявку. Достаточно одного агента с доступом к рабочей папке; дополнительные сервисы подключаются по необходимости.\n\nТексты курса подготовлены для Elaz Ed. Закрытые материалы, пресеты, чат и частный MCP другого автора в него не входят.","emoji":"🎬","gradient":"sunset","price_stars":0,"invite_unlock":0,"position":0,"published":true},"lessons":[{"key":"feed-1","source_index":1,"source_type":"tool","title":"blocks.so: готовые блоки для сайта","category":"Дизайн","subtitle":"Формы, навигацию, таблицы и целые экраны можно начать с готового кода из blocks.so.","cover_url":"https://proninlearn.ru/posts/blocks-so-604w.webp","minutes":2,"xp":20,"body":"Формы, навигацию, таблицы и целые экраны можно начать с готового кода из blocks.so. Передай агенту выбранный компонент и объясни, какие данные и действия нужны в твоём интерфейсе. Так базовая вёрстка уже есть, а время уходит на задачу проекта.\n\n## Открыть ресурс\n\n- [blocks.so](https://blocks.so/)","copy_text":null,"quiz":[],"published":true,"kind":"lesson","emoji":"🎨","gradient":"aurora","video_url":null,"pinned":false,"position":1,"free_preview":false,"course_key":null},{"key":"feed-2","source_index":2,"source_type":"tool","title":"Google Foresight: заметки после встреч","category":"Прочее","subtitle":"Foresight помогает дополнить короткие записи подробностями из аудио встречи.","cover_url":"https://proninlearn.ru/posts/google-foresight-604w.webp","minutes":2,"xp":20,"body":"Foresight помогает дополнить короткие записи подробностями из аудио встречи. В исходной подборке описана локальная работа на Mac с Apple Silicon: набрасываешь тезисы, приложение восстанавливает контекст разговора и договорённости. Перед установкой сверь требования устройства на странице разработчика.\n\n## Открыть ресурс\n\n- [developers.google.com](https://developers.google.com/)","copy_text":null,"quiz":[],"published":true,"kind":"lesson","emoji":"🧰","gradient":"sunset","video_url":null,"pinned":false,"position":2,"free_preview":false,"course_key":null},{"key":"feed-3","source_index":3,"source_type":"tool","title":"Sileo: уведомления с плавными переходами","category":"Дизайн","subtitle":"Sileo даёт React-проекту анимированные сообщения о загрузке, успешном действии и ошибке.","cover_url":"https://proninlearn.ru/posts/sileo-604w.webp","minutes":2,"xp":20,"body":"Sileo даёт React-проекту анимированные сообщения о загрузке, успешном действии и ошибке. Одно уведомление меняет форму и состояние по мере выполнения задачи, а при необходимости раскрывает подробности. Подходит для сохранения формы и загрузки файлов, когда хочется согласованной анимации без разработки каждого перехода вручную.\n\n## Открыть ресурс\n\n- [sileo.aaryan.design](https://sileo.aaryan.design/)","copy_text":null,"quiz":[],"published":true,"kind":"lesson","emoji":"🎨","gradient":"mint","video_url":null,"pinned":false,"position":3,"free_preview":false,"course_key":null},{"key":"feed-4","source_index":4,"source_type":"tool","title":"GSAP Skills: научить агента анимации","category":"Дизайн","subtitle":"Набор навыков объясняет агенту приёмы GSAP: работу с таймлайнами, появление текста, движение карточек и эффекты прокрутки.","cover_url":"https://proninlearn.ru/posts/gsap-skills-604w.webp","minutes":2,"xp":20,"body":"Набор навыков объясняет агенту приёмы GSAP: работу с таймлайнами, появление текста, движение карточек и эффекты прокрутки. В подборке — восемь навыков для Claude Code, Codex и Cursor. Подключи нужный и задай конкретный сценарий движения, затем проверь результат в браузере.\n\n## Открыть ресурс\n\n- [github.com](https://github.com/greensock/gsap-skills)","copy_text":null,"quiz":[],"published":true,"kind":"lesson","emoji":"🎨","gradient":"ocean","video_url":null,"pinned":false,"position":4,"free_preview":false,"course_key":null},{"key":"feed-5","source_index":5,"source_type":"tool","title":"Page Mascot: персонаж для интерфейса","category":"Дизайн","subtitle":"Готовые маскоты реагируют на движение указателя и клики.","cover_url":"https://proninlearn.ru/posts/page-mascot-604w.webp","minutes":2,"xp":20,"body":"Готовые маскоты реагируют на движение указателя и клики. Можно выбрать медведя, кота, кролика и других персонажей, а навык поможет агенту встроить их в проект. Для лендинга или портфолио достаточно одного персонажа в месте, где он поддерживает содержание и не перекрывает кнопки.\n\n## Открыть ресурс\n\n- [koboyo.com](https://koboyo.com/)","copy_text":null,"quiz":[],"published":true,"kind":"lesson","emoji":"🎨","gradient":"candy","video_url":null,"pinned":false,"position":5,"free_preview":false,"course_key":null},{"key":"feed-6","source_index":6,"source_type":"tool","title":"Agentation: объяснять правки прямо на странице","category":"Дизайн","subtitle":"С Agentation замечание привязывается к элементу интерфейса.","cover_url":"https://proninlearn.ru/posts/agentation-604w.webp","minutes":2,"xp":20,"body":"С Agentation замечание привязывается к элементу интерфейса. Выбираешь карточку или кнопку, пишешь, что исправить, и агент получает комментарий вместе с контекстом через MCP. Это сокращает поиск нужного места и помогает обсуждать размеры, отступы и поведение на конкретном экране.\n\n## Открыть ресурс\n\n- [agentation.com](https://agentation.com/)","copy_text":null,"quiz":[],"published":true,"kind":"lesson","emoji":"🎨","gradient":"lime","video_url":null,"pinned":false,"position":6,"free_preview":false,"course_key":null},{"key":"feed-7","source_index":7,"source_type":"tool","title":"OnePromptDesign: запросы с примерами результата","category":"Промпты","subtitle":"В OnePromptDesign можно подобрать запрос для рекламного изображения, постера, фона или макета по готовому примеру.","cover_url":"https://proninlearn.ru/posts/onepromptdesign-604w.webp","minutes":2,"xp":20,"body":"В OnePromptDesign можно подобрать запрос для рекламного изображения, постера, фона или макета по готовому примеру. Выбери подходящее визуальное направление, затем поменяй объект, содержание и ограничения под свой проект. Пример помогает понять, какой результат ожидается от запроса.\n\n## Открыть ресурс\n\n- [onepromptdesign.com](https://onepromptdesign.com/)","copy_text":null,"quiz":[],"published":true,"kind":"lesson","emoji":"💬","gradient":"aurora","video_url":null,"pinned":false,"position":7,"free_preview":false,"course_key":null},{"key":"feed-8","source_index":8,"source_type":"tool","title":"Shaders: готовые эффекты для веба","category":"Дизайн","subtitle":"Стекло, жидкий металл, космические фоны и реакция на курсор доступны как готовые эффекты.","cover_url":"https://proninlearn.ru/posts/shaders-604w.webp","minutes":2,"xp":20,"body":"Стекло, жидкий металл, космические фоны и реакция на курсор доступны как готовые эффекты. Навык и MCP помогают агенту выбрать эффект и встроить его в страницу. У библиотеки есть бесплатная часть и платные Pro-наборы; условия конкретного эффекта проверяй перед использованием.\n\n## Открыть ресурс\n\n- [shaders.com](https://shaders.com/)","copy_text":null,"quiz":[],"published":true,"kind":"lesson","emoji":"🎨","gradient":"sunset","video_url":null,"pinned":false,"position":8,"free_preview":false,"course_key":null},{"key":"feed-9","source_index":9,"source_type":"tool","title":"Когда восстановятся лимиты ИИ-сервисов","category":"Прочее","subtitle":"Три сервиса из подборки помогают следить за восстановлением лимитов: codex-reset показывает прогноз для Codex, limitreset собирает уведомления по нескольким инструментам, claude-resets сообщает о сбросе Claude по почте.","cover_url":"https://proninlearn.ru/posts/codex-reset-512w.webp","minutes":2,"xp":20,"body":"Три сервиса из подборки помогают следить за восстановлением лимитов: codex-reset показывает прогноз для Codex, limitreset собирает уведомления по нескольким инструментам, claude-resets сообщает о сбросе Claude по почте. Такие оценки удобно использовать для планирования работы; точное состояние своего аккаунта проверяй также в самом сервисе.\n\n## Открыть ресурс\n\n- [codex-reset.com](https://codex-reset.com/)\n- [limitreset.net](https://limitreset.net/)\n- [claude-resets.net](https://claude-resets.net/)\n\n![Пример из подборки](https://proninlearn.ru/posts/limitreset-512w.webp)\n\n![Пример из подборки](https://proninlearn.ru/posts/claude-resets-512w.webp)","copy_text":null,"quiz":[],"published":true,"kind":"lesson","emoji":"🧰","gradient":"mint","video_url":null,"pinned":false,"position":9,"free_preview":false,"course_key":null},{"key":"feed-10","source_index":10,"source_type":"tool","title":"last30days: собрать свежие тренды","category":"Прочее","subtitle":"Навык ищет обсуждения в социальных источниках и сводит находки в обзор.","cover_url":"https://proninlearn.ru/posts/last30days-604w.webp","minutes":2,"xp":20,"body":"Навык ищет обсуждения в социальных источниках и сводит находки в обзор. Повторяющиеся темы из разных площадок помогают отделить устойчивый сигнал от одного популярного поста. Задай тему, период и аудиторию; в результате проси ссылки, даты и объяснение того, почему тренд попал в подборку.\n\n## Открыть ресурс\n\n- [github.com](https://github.com/mvanhorn/last30days-skill)","copy_text":null,"quiz":[],"published":true,"kind":"lesson","emoji":"🧰","gradient":"ocean","video_url":null,"pinned":false,"position":10,"free_preview":false,"course_key":null},{"key":"feed-11","source_index":11,"source_type":"tool","title":"Astryx: компоненты в единой системе","category":"Дизайн","subtitle":"Astryx объединяет компоненты, темы и шаблоны интерфейса.","cover_url":"https://proninlearn.ru/posts/astryx-604w.webp","minutes":2,"xp":20,"body":"Astryx объединяет компоненты, темы и шаблоны интерфейса. Начни с экрана, похожего на нужный сценарий, затем адаптируй тексты и состояния. Единые правила для цвета, типографики и расстояний помогают новым экранам сочетаться с уже собранными.\n\n## Открыть ресурс\n\n- [astryx.atmeta.com](https://astryx.atmeta.com/)","copy_text":null,"quiz":[],"published":true,"kind":"lesson","emoji":"🎨","gradient":"candy","video_url":null,"pinned":false,"position":11,"free_preview":false,"course_key":null},{"key":"feed-12","source_index":12,"source_type":"tool","title":"Iconimate: иконки с готовым движением","category":"Дизайн","subtitle":"В исходной подборке Iconimate содержит больше двухсот анимированных иконок.","cover_url":"https://proninlearn.ru/posts/iconimate-604w.webp","minutes":2,"xp":20,"body":"В исходной подборке Iconimate содержит больше двухсот анимированных иконок. Выбери символ под действие и используй его готовое движение в интерфейсе или ролике. Проверь, что анимация понятна и в маленьком размере, а частота повторения не отвлекает от задачи.\n\n## Открыть ресурс\n\n- [iconimate.app](https://iconimate.app/)","copy_text":null,"quiz":[],"published":true,"kind":"lesson","emoji":"🎨","gradient":"lime","video_url":null,"pinned":false,"position":12,"free_preview":false,"course_key":null},{"key":"feed-13","source_index":13,"source_type":"tool","title":"Dot Matrix: загрузка из точек","category":"Дизайн","subtitle":"Точки собираются в фигуры, вращаются и меняют рисунок.","cover_url":"https://proninlearn.ru/posts/dotmatrix-604w.webp","minutes":2,"xp":20,"body":"Точки собираются в фигуры, вращаются и меняют рисунок. Готовые варианты Dot Matrix подходят для состояния ожидания в приложении. Настрой палитру под проект и оставь человеку понятное пояснение о том, что загружается: движение само по себе не объясняет состояние.\n\n## Открыть ресурс\n\n- [dotmatrix.zzzzshawn.cloud](https://dotmatrix.zzzzshawn.cloud/)","copy_text":null,"quiz":[],"published":true,"kind":"lesson","emoji":"🎨","gradient":"aurora","video_url":null,"pinned":false,"position":13,"free_preview":false,"course_key":null},{"key":"feed-14","source_index":14,"source_type":"tool","title":"CodeNotch: расход лимитов рядом с экраном","category":"Прочее","subtitle":"Небольшой виджет показывает расход лимитов инструментов разработки, включая Claude Code и Codex.","cover_url":"https://proninlearn.ru/posts/codenotch-604w.webp","minutes":2,"xp":20,"body":"Небольшой виджет показывает расход лимитов инструментов разработки, включая Claude Code и Codex. Он закрепляется у края экрана, поэтому состояние видно без отдельного захода в настройки. Посмотри список поддерживаемых сервисов и способ получения данных в документации своей версии.\n\n## Открыть ресурс\n\n- [github.com](https://github.com/vinzdg/codenotch)","copy_text":null,"quiz":[],"published":true,"kind":"lesson","emoji":"🧰","gradient":"sunset","video_url":null,"pinned":false,"position":14,"free_preview":false,"course_key":null},{"key":"feed-15","source_index":15,"source_type":"tool","title":"Doodle Icons: линии, которые рисуются сами","category":"Дизайн","subtitle":"Рисованные иконки дают кадру ощущение живого наброска.","cover_url":"https://proninlearn.ru/posts/doodle-icons-604w.webp","minutes":2,"xp":20,"body":"Рисованные иконки дают кадру ощущение живого наброска. В анимированных вариантах штрих появляется постепенно и продолжает слегка двигаться. Используй их для объясняющих роликов, схем и небольших акцентов; рядом лучше работают простые подписи и спокойные элементы управления.\n\n## Открыть ресурс\n\n- [github.com](https://github.com/oreo-design/doodle-icons)","copy_text":null,"quiz":[],"published":true,"kind":"lesson","emoji":"🎨","gradient":"mint","video_url":null,"pinned":false,"position":15,"free_preview":false,"course_key":null},{"key":"feed-16","source_index":16,"source_type":"tool","title":"ArloUI: основа мобильного интерфейса","category":"Дизайн","subtitle":"ArloUI предлагает кнопки, поля, карточки, переключатели, галереи, карусели и вкладки для мобильных приложений.","cover_url":"https://proninlearn.ru/posts/arloui-604w.webp","minutes":2,"xp":20,"body":"ArloUI предлагает кнопки, поля, карточки, переключатели, галереи, карусели и вкладки для мобильных приложений. Собирай экран из согласованных компонентов, затем проверяй удобство касания и состояния каждого элемента. Готовая система ускоряет старт, но содержание и сценарий остаются задачей проекта.\n\n## Открыть ресурс\n\n- [arloui.com](https://arloui.com/)","copy_text":null,"quiz":[],"published":true,"kind":"lesson","emoji":"🎨","gradient":"ocean","video_url":null,"pinned":false,"position":16,"free_preview":false,"course_key":null},{"key":"feed-17","source_index":17,"source_type":"tool","title":"Duck.ai: попробовать чат с моделями","category":"Прочее","subtitle":"Duck.ai позволяет начать разговор с несколькими моделями без покупки отдельной подписки на каждую.","cover_url":"https://proninlearn.ru/posts/duckai-604w.webp","minutes":2,"xp":20,"body":"Duck.ai позволяет начать разговор с несколькими моделями без покупки отдельной подписки на каждую. Подходит для черновиков и сравнения ответов на небольших задачах. Набор доступных моделей и лимиты меняются, поэтому ориентируйся на список внутри сервиса.\n\n## Открыть ресурс\n\n- [duck.ai](https://duck.ai/)","copy_text":null,"quiz":[],"published":true,"kind":"lesson","emoji":"🧰","gradient":"candy","video_url":null,"pinned":false,"position":17,"free_preview":false,"course_key":null},{"key":"feed-18","source_index":18,"source_type":"tool","title":"HeroUI: компоненты и документация для агента","category":"Дизайн","subtitle":"В исходной подборке HeroUI описан как React-набор из 71 компонента под MIT.","cover_url":"https://proninlearn.ru/posts/heroui-604w.webp","minutes":2,"xp":20,"body":"В исходной подборке HeroUI описан как React-набор из 71 компонента под MIT. Документация в формате llms.txt помогает передать агенту целостную справку. Проси использовать компоненты библиотеки по её правилам, включая состояния, доступность и тему проекта.\n\n## Открыть ресурс\n\n- [heroui.com](https://heroui.com/)","copy_text":null,"quiz":[],"published":true,"kind":"lesson","emoji":"🎨","gradient":"lime","video_url":null,"pinned":false,"position":18,"free_preview":false,"course_key":null},{"key":"feed-19","source_index":19,"source_type":"tool","title":"Три библиотеки визуальных референсов","category":"Дизайн","subtitle":"posts.design, recent.design и inspora.design пригодятся для поиска моушна, веб-интерфейсов, брендинга, 3D и небольших обложек.","cover_url":"https://proninlearn.ru/posts/socialposts-512w.webp","minutes":2,"xp":20,"body":"posts.design, recent.design и inspora.design пригодятся для поиска моушна, веб-интерфейсов, брендинга, 3D и небольших обложек. Сохрани несколько примеров, затем выпиши, что именно в них полезно: ритм, типографика, композиция или движение. Это даст агенту конкретное направление для своего решения.\n\n## Открыть ресурс\n\n- [posts.design](https://posts.design/)\n- [recent.design](https://recent.design/)\n- [inspora.design](https://inspora.design/)\n\n![Пример из подборки](https://proninlearn.ru/posts/recent-512w.webp)\n\n![Пример из подборки](https://proninlearn.ru/posts/inspora-512w.webp)","copy_text":null,"quiz":[],"published":true,"kind":"lesson","emoji":"🎨","gradient":"aurora","video_url":null,"pinned":false,"position":19,"free_preview":false,"course_key":null},{"key":"feed-20","source_index":20,"source_title":"Словарик вайбкодера, часть первая","source_type":"guide","title":"Словарь разработчика: 18 понятий для работы с ИИ","category":"Нейронки","subtitle":"Агент предлагает поставить rate limit или добавить транзакцию. Чтобы принять такое решение, нужно понимать, что изменится в продукте. Ниже восемнадцать базовых понятий: назначение, цена отсутствия и вопрос для проверки.","body":"Агент предлагает поставить rate limit или добавить транзакцию. Чтобы принять такое решение, нужно понимать, что изменится в продукте. Ниже восемнадцать базовых понятий: назначение, цена отсутствия и вопрос для проверки.\n\n## CI/CD\n\nПосле отправки изменений конвейер собирает проект, проверяет типы и запускает тесты. Деплой начинается после успешных проверок. Это помогает поймать ситуацию, когда исправление одного экрана ломает соседний. Уточни, какие проверки действительно запускаются и какая ветка попадает на сервер.\n\n## Rate limit\n\nОграничение числа запросов за период. При превышении сервер может ответить 429. У входа, оплаты и отправки СМС разные лимиты, потому что у запросов разная стоимость. Проверяй ограничение на сервере и выбранный идентификатор клиента; счётчик только на кнопке обходится прямым запросом.\n\n## Cron\n\nЗадача запускается по расписанию без действия пользователя. Например, `0 3 * * *` означает ежедневный запуск в 03:00 в часовом поясе планировщика. Так делают отчёты и напоминания. Продумай, что произойдёт при повторном запуске и работе нескольких серверов.\n\n## Индекс\n\nИндекс помогает базе находить строки по нужным полям быстрее полного перебора. На сотнях записей разница бывает незаметной, на сотнях тысяч становится важной. Индекс занимает место и увеличивает работу при записи, поэтому выбирают его под реальные запросы и проверяют план выполнения.\n\n## Миграция\n\nИзменения структуры базы сохраняются последовательными шагами рядом с кодом: таблица, колонка, индекс. По ним можно развернуть нужную схему в другой среде. Откат существует только там, где он предусмотрен; удалённые данные требуют отдельного восстановления.\n\n## Транзакция\n\nНесколько изменений базы подтверждаются вместе: либо все, либо ни одно. Например, изменение баланса и запись операции должны согласовываться. Внешний платёж и база не становятся одной транзакцией автоматически — для этого нужны обработка событий и сверка. Проверь, что сбой между шагами не оставляет неверное состояние.\n\n## Кэш\n\nГотовый результат сохраняется для повторного использования. Это уменьшает расчёты и обращения к базе. Обратная сторона — старые цены или остатки, пока кэш не обновлён. Укажи срок жизни и события, при которых он сбрасывается.\n\n## .env\n\nЛокальный файл содержит значения переменных окружения: адрес сервиса, ключ, параметры среды. Секреты в репозиторий не кладут; на сервере их настраивают отдельно. Добавление имени переменной в код не означает, что её значение уже появилось на хостинге. Утёкший ключ сначала отзывают и заменяют.\n\n## Хэш пароля\n\nПароль хранится в виде результата специального медленного алгоритма с солью. При входе библиотека проверяет введённое значение. Подходят предназначенные для паролей алгоритмы, например Argon2id или bcrypt; обычные MD5 и SHA-1 для этой задачи не подходят. Хэш усложняет подбор, но не делает слабый пароль неуязвимым.\n\n## CORS\n\nБраузер проверяет, каким сайтам сервер разрешает читать ответы своего API. Укажи нужные origins и способ передачи credentials. CORS не заменяет авторизацию и защиту от CSRF: запросы вне браузера этим правилом не ограничены.\n\n## Webhook\n\nСервис сам сообщает о событии HTTP-запросом: оплате, доставке или смене статуса. Обработчик проверяет подпись до записи данных. Уведомления могут повторяться или задерживаться, поэтому нужны идемпотентность и периодическая сверка незавершённых операций.\n\n## Идемпотентность\n\nПовтор той же операции даёт один результат. Ключ заказа или уникальный идентификатор события помогает не начислить доступ дважды после повторного вебхука. Важно, чтобы проверка и изменение были согласованы также при одновременных запросах.\n\n## Таймаут\n\nОпределяет предел ожидания ответа внешнего сервиса. Бесконечное ожидание занимает ресурсы, слишком короткий предел создаёт ошибки на нормальных запросах. Значение выбирают по измерениям; отдельно описывают повторы и поведение интерфейса после отказа.\n\n## Очередь\n\nПисьмо, обработка изображения или тяжёлый отчёт выполняются фоновым работником. Пользователь получает подтверждение раньше завершения работы. У очереди нужны повторные попытки, паузы между ними и место для задач, которые постоянно падают.\n\n## Логи\n\nЖурнал связывает время, событие, этап и результат. Номер заказа, код ошибки и идентификатор запроса помогают восстановить цепочку. Пароли, токены и полные чувствительные данные маскируют. Пишущийся журнал полезен, когда его можно найти и сопоставить с жалобой.\n\n## Staging\n\nСреда для проверки до публикации: близкие к продакшену код и схема, отдельные данные и тестовые платёжные ключи. Она помогает увидеть проблему без воздействия на покупателей. Проверь, что случайная проверка не создаёт настоящее списание.\n\n## Бэкап\n\nКопия лежит отдельно от рабочего сервера и создаётся по расписанию. Проверка восстановления подтверждает, что данные можно использовать. Запиши периодичность, срок хранения, допустимую потерю данных и время восстановления.\n\n## Токены\n\nМодель обрабатывает текст частями, которые называются токенами. Они влияют на размер контекста и цену API-запроса. Отношение токенов к символам зависит от языка и модели. Договорённости и правила сохраняй в файлах: длинный чат не даёт гарантии, что вся история остаётся доступной.\n\n## Проверка понимания\n\nПопроси агента разделить отчёт на сделанное в коде, настроенное на сервере и оставшееся действие человека. Так рекомендация «использовать .env» не будет выглядеть как уже выполненная настройка секретов.","cover_url":null,"minutes":5,"xp":60,"copy_text":null,"quiz":[],"published":true,"kind":"lesson","emoji":"🤖","gradient":"sunset","video_url":null,"pinned":false,"position":20,"free_preview":false,"course_key":null},{"key":"feed-21","source_index":21,"source_title":"Пайплайн презентаций с дашбордами","source_type":"guide","title":"Презентации с дашбордами: от установки до PDF","category":"Нейронки","subtitle":"Система из исходного материала объединяет холст презентации, готовые блоки и карточки с данными. Агент устанавливает проект, собирает слайды и проверяет экспорт. Рабочее место — Storybook, где блоки видны по отдельности.","body":"Система из исходного материала объединяет холст презентации, готовые блоки и карточки с данными. Агент устанавливает проект, собирает слайды и проверяет экспорт. Рабочее место — Storybook, где блоки видны по отдельности.\n\n## Состав системы\n\n- 43 блока и 24 карточки с графиками, таблицами, воронками, календарями и перепиской.\n- Светлая и тёмная темы, включая карточки одной темы на слайде другой.\n- 66 витрин и 445 примеров в Storybook.\n- Семь правил и четыре процедуры: new-slide, new-deck, export-pdf, port-component.\n- Демонстрация из девяти слайдов и минимальная презентация из трёх.\n\nЭто характеристики архива от 22 августа 2026 года. Холст — 1920×1080. Внутренняя область — 1680×904; сетка состоит из двенадцати колонок по 118 и одиннадцати промежутков по 24. Дробить текст до размера, удобного только на мониторе автора, нельзя: результат должны читать с расстояния.\n\n## Что показывать каким блоком\n\nВоронка показывает потери между этапами. Кольца подходят для показателей с разными нормами. Календарь вклада раскрывает ритм периода. Столбцы вместе с линией связывают объём и накопленную долю. Две площади сравнивают сценарии. Переписка помогает показать аргумент в репликах. Мокап объясняет продуктовый экран, а полоса состава — доли и пороги. Месяц с кольцами показывает дневной ритм.\n\n## Установка\n\n[Скачать исходный архив системы](https://proninlearn.ru/downloads/slide-system-2026-08-22.zip). В исходной публикации архив занимает 1,5 МБ и содержит папку slide-system с 230 файлами.\n\nПередай агенту путь к скачанному архиву. Попроси распаковать его в рабочую папку, проверить Node.js 20 или новее, установить зависимости и браузер Chromium для Playwright. Затем запустить Storybook и `npm run check`.\n\n```text\nНастрой проект из архива slide-system. До установки прочитай правила и package.json. Проверь версию Node, установи зависимости и браузер для Playwright. Запусти витрину и проверку слайдов. Покажи адрес витрины и результаты проверки showcase и example. Перед первой правкой прочитай .claude/rules и доступные .claude/skills.\n```\n\nБраузер скачивается отдельно и хранится в общем кэше машины. Цифры размеров зависят от версии. Успех установки подтверждается открытой витриной и проверками обеих демонстрационных презентаций, а не одним завершившимся npm install.\n\n## Первый набор слайдов\n\nnew-deck создаёт папку, порядок слайдов в манифесте и запись в реестре. new-slide собирает отдельный экран из блоков. Задай аудиторию, главную мысль и исходные данные. Например: шесть слайдов об итогах квартала для клиента, основной вывод — рост выручки за два квартала.\n\nКаждый слайд проверь в двух темах, на переполнение и на соблюдение токенов системы. Для диаграммы нужны подписи единиц, период и источник данных.\n\n## Экспорт\n\nВ исходной системе PDF строится из снимков слайдов 3840×2160. Это растровые страницы: текст в них не выделяется. Если нужен поиск и выделение текста, такой способ экспорта нужно заменить или дополнить.\n\nПеред сдачей проверь порядок слайдов, появление своей презентации в реестре, отсутствие дефектов при проверке и наличие PDF в export. Открой готовый PDF и просмотри все страницы.","cover_url":null,"minutes":3,"xp":60,"copy_text":null,"quiz":[],"published":true,"kind":"lesson","emoji":"🤖","gradient":"mint","video_url":null,"pinned":false,"position":21,"free_preview":false,"course_key":null},{"key":"feed-22","source_index":22,"source_type":"tool","title":"Morphicons: переход между двумя иконками","category":"Дизайн","subtitle":"В Morphicons один знак плавно превращается в другой.","cover_url":"https://proninlearn.ru/posts/morphicons-604w.webp","minutes":2,"xp":20,"body":"В Morphicons один знак плавно превращается в другой. Набор включает варианты из Lucide, Tabler, Heroicons и других семейств. Такой переход полезен при смене состояния кнопки, например между меню и закрытием. В подборке указаны MIT и небольшой размер библиотеки; актуальную сборку сверяй в документации.\n\n## Открыть ресурс\n\n- [morphicons.com](https://morphicons.com/)","copy_text":null,"quiz":[],"published":true,"kind":"lesson","emoji":"🎨","gradient":"ocean","video_url":null,"pinned":false,"position":22,"free_preview":false,"course_key":null},{"key":"feed-23","source_index":23,"source_type":"tool","title":"Tweakcn: настроить внешний вид shadcn","category":"Дизайн","subtitle":"Tweakcn даёт менять цвета, шрифты, радиусы и тени рядом с живым примером интерфейса.","cover_url":"https://proninlearn.ru/posts/tweakcn-604w.webp","minutes":2,"xp":20,"body":"Tweakcn даёт менять цвета, шрифты, радиусы и тени рядом с живым примером интерфейса. Когда система выглядит цельно, экспортируй CSS и передай его агенту как набор правил. Проверяй контраст и длинные тексты в обеих темах до переноса во весь проект.\n\n## Открыть ресурс\n\n- [tweakcn.com](https://tweakcn.com/)","copy_text":null,"quiz":[],"published":true,"kind":"lesson","emoji":"🎨","gradient":"candy","video_url":null,"pinned":false,"position":23,"free_preview":false,"course_key":null},{"key":"feed-24","source_index":24,"source_type":"tool","title":"Fontshare: шрифты и готовые сочетания","category":"Дизайн","subtitle":"В подборке Fontshare — сто шрифтов и 59 пар для заголовков и основного текста.","cover_url":"https://proninlearn.ru/posts/fontshare-604w.webp","minutes":2,"xp":20,"body":"В подборке Fontshare — сто шрифтов и 59 пар для заголовков и основного текста. Сервис удобен, когда нужно подобрать контраст между гарнитурами и разместить файлы на своём сервере. Перед скачиванием проверь лицензию выбранной семьи и наличие нужного языка.\n\n## Открыть ресурс\n\n- [fontshare.com](https://fontshare.com/)","copy_text":null,"quiz":[],"published":true,"kind":"lesson","emoji":"🎨","gradient":"lime","video_url":null,"pinned":false,"position":24,"free_preview":false,"course_key":null},{"key":"feed-25","source_index":25,"source_type":"tool","title":"Iconify: поиск по разным наборам иконок","category":"Дизайн","subtitle":"Iconify объединяет много открытых семейств в одном поиске.","cover_url":"https://proninlearn.ru/posts/iconify-604w.webp","minutes":2,"xp":20,"body":"Iconify объединяет много открытых семейств в одном поиске. В исходной подборке указаны 325 тысяч иконок из 220 наборов. У каждого семейства своя лицензия, поэтому выбирай не только по рисунку: сверь правила использования и старайся держать один стиль внутри экрана.\n\n## Открыть ресурс\n\n- [icon-sets.iconify.design](https://icon-sets.iconify.design/)","copy_text":null,"quiz":[],"published":true,"kind":"lesson","emoji":"🎨","gradient":"aurora","video_url":null,"pinned":false,"position":25,"free_preview":false,"course_key":null},{"key":"feed-26","source_index":26,"source_type":"tool","title":"3dicons: объёмные предметы для дизайна","category":"Дизайн","subtitle":"3dicons предлагает объёмные иконки предметов в нескольких ракурсах.","cover_url":"https://proninlearn.ru/posts/icons3d-604w.webp","minutes":2,"xp":20,"body":"3dicons предлагает объёмные иконки предметов в нескольких ракурсах. Исходная подборка описывает 200 объектов и 1400 рендеров под CC0. Их удобно брать для обложек, карточек и роликов; заранее проверь, совпадает ли направление света и перспектива у соседних изображений.\n\n## Открыть ресурс\n\n- [3dicons.co](https://3dicons.co/)","copy_text":null,"quiz":[],"published":true,"kind":"lesson","emoji":"🎨","gradient":"sunset","video_url":null,"pinned":false,"position":26,"free_preview":false,"course_key":null},{"key":"feed-27","source_index":27,"source_type":"tool","title":"21st.dev: компоненты через запрос агенту","category":"Дизайн","subtitle":"На 21st.dev можно найти готовый React-блок и передать агенту запрос для его установки.","cover_url":"https://proninlearn.ru/posts/blocks21-604w.webp","minutes":2,"xp":20,"body":"На 21st.dev можно найти готовый React-блок и передать агенту запрос для его установки. В подборке — около 12 тысяч блоков и компонентов. После переноса проверь зависимости, адаптивность и соответствие теме: выбранный пример должен стать частью твоего интерфейса.\n\n## Открыть ресурс\n\n- [21st.dev](https://21st.dev/)","copy_text":null,"quiz":[],"published":true,"kind":"lesson","emoji":"🎨","gradient":"mint","video_url":null,"pinned":false,"position":27,"free_preview":false,"course_key":null},{"key":"feed-28","source_index":28,"source_type":"tool","title":"Bloub: собрать анимированного маскота","category":"Дизайн","subtitle":"Bloub позволяет выбрать форму, выражение и анимационное состояние персонажа.","cover_url":"https://proninlearn.ru/posts/bloub-604w.webp","minutes":2,"xp":20,"body":"Bloub позволяет выбрать форму, выражение и анимационное состояние персонажа. В исходной версии — восемь форм, шестнадцать выражений и четырнадцать состояний. Готовый цикл экспортируется в MP4 или SVG и подходит для заставки, реакции в ролике или небольшого героя на странице.\n\n## Открыть ресурс\n\n- [bloub.vercel.app](https://bloub.vercel.app/)","copy_text":null,"quiz":[],"published":true,"kind":"lesson","emoji":"🎨","gradient":"ocean","video_url":null,"pinned":false,"position":28,"free_preview":false,"course_key":null},{"key":"feed-29","source_index":29,"source_type":"prompt","title":"Аудит проекта по OWASP Top 10:2025","category":"Безопасность","subtitle":"Пройти все десять классов и показать доказательства","body":"Пройти все десять классов и показать доказательства. Подставь свои данные в квадратные скобки и передай запрос агенту.\n\n```text\nИсследуй мой проект по OWASP Top 10:2025. Область проверки: клиент, сервер, конфигурация и доступные зависимости. До запуска активных проверок обозначь их воздействие; используй только разрешённую среду.\n\nПроверь все категории: A01 — права доступа; A02 — конфигурация; A03 — цепочка поставок; A04 — криптография; A05 — инъекции; A06 — проектирование; A07 — аутентификация; A08 — целостность; A09 — журналы и оповещения; A10 — исключительные условия.\n\nДля каждой укажи один статус: подтверждённая проблема; проверенные сценарии прошли; неприменимо с причиной; недостаточно данных. Последний статус используй вместо догадок.\n\nДля находки нужны файл и строка, условия воспроизведения, вход атакующего, получаемый эффект, уровень риска с объяснением и предложение исправления. Отдельно проверь принадлежность объектов и серверные ограничения: скрытая кнопка не подтверждает защиту.\n\nНа первом проходе код не меняй. Заверши таблицей результатов и списком того, что требует запуска, сведений о деплое или ручной проверки.\n```","copy_text":"Исследуй мой проект по OWASP Top 10:2025. Область проверки: клиент, сервер, конфигурация и доступные зависимости. До запуска активных проверок обозначь их воздействие; используй только разрешённую среду.\n\nПроверь все категории: A01 — права доступа; A02 — конфигурация; A03 — цепочка поставок; A04 — криптография; A05 — инъекции; A06 — проектирование; A07 — аутентификация; A08 — целостность; A09 — журналы и оповещения; A10 — исключительные условия.\n\nДля каждой укажи один статус: подтверждённая проблема; проверенные сценарии прошли; неприменимо с причиной; недостаточно данных. Последний статус используй вместо догадок.\n\nДля находки нужны файл и строка, условия воспроизведения, вход атакующего, получаемый эффект, уровень риска с объяснением и предложение исправления. Отдельно проверь принадлежность объектов и серверные ограничения: скрытая кнопка не подтверждает защиту.\n\nНа первом проходе код не меняй. Заверши таблицей результатов и списком того, что требует запуска, сведений о деплое или ручной проверки.","cover_url":null,"minutes":3,"xp":30,"quiz":[],"published":true,"kind":"lesson","emoji":"🛡️","gradient":"candy","video_url":null,"pinned":false,"position":29,"free_preview":false,"course_key":null},{"key":"feed-30","source_index":30,"source_type":"prompt","title":"Интервью перед разработкой","category":"Промпты","subtitle":"Уточнить задачу по одному вопросу и получить план","body":"Уточнить задачу по одному вопросу и получить план. Подставь свои данные в квадратные скобки и передай запрос агенту.\n\n```text\nПомоги спланировать проект [описание проекта]. Сначала выясни мой опыт: писал ли я код, работал ли с таким стеком и что делал самостоятельно. Объяснения дальше строй на этом уровне, незнакомые термины раскрывай.\n\nЗадавай по одному вопросу и жди ответ. Выясни конечный результат, аудиторию, исходные материалы и уже работающие части, бюджет и время, критерий готовности и исключения из объёма.\n\nЕсли ответ содержит «удобно», «быстро» или другое общее пожелание, попроси пример либо измеримый критерий. Не затягивай интервью вопросами, которые не меняют план.\n\nКогда информации достаточно, предложи последовательность шагов, способ проверки каждого и основные риски. Раздели принятые мной решения, твои допущения и оставшиеся неизвестные. Для неизвестного укажи способ проверки. Не начинай реализацию, пока согласуем этот план.\n```","copy_text":"Помоги спланировать проект [описание проекта]. Сначала выясни мой опыт: писал ли я код, работал ли с таким стеком и что делал самостоятельно. Объяснения дальше строй на этом уровне, незнакомые термины раскрывай.\n\nЗадавай по одному вопросу и жди ответ. Выясни конечный результат, аудиторию, исходные материалы и уже работающие части, бюджет и время, критерий готовности и исключения из объёма.\n\nЕсли ответ содержит «удобно», «быстро» или другое общее пожелание, попроси пример либо измеримый критерий. Не затягивай интервью вопросами, которые не меняют план.\n\nКогда информации достаточно, предложи последовательность шагов, способ проверки каждого и основные риски. Раздели принятые мной решения, твои допущения и оставшиеся неизвестные. Для неизвестного укажи способ проверки. Не начинай реализацию, пока согласуем этот план.","cover_url":null,"minutes":3,"xp":30,"quiz":[],"published":true,"kind":"lesson","emoji":"💬","gradient":"lime","video_url":null,"pinned":false,"position":30,"free_preview":false,"course_key":null},{"key":"feed-31","source_index":31,"source_type":"prompt","title":"Проверка обработки персональных данных","category":"Закон","subtitle":"Девять пунктов с фактами и вопросами для юриста","body":"Девять пунктов с фактами и вопросами для юриста. Подставь свои данные в квадратные скобки и передай запрос агенту.\n\n```text\nСоставь фактическую проверку сайта [адрес или проект] по вопросам обработки персональных данных. Сначала установи юрисдикцию и применимость требований. Для правовых выводов используй действующие официальные источники с датой проверки.\n\nПо девяти пунктам укажи: есть; отсутствует; неприменимо с обоснованием; проверить невозможно по доступным данным.\n1. Публичная политика доступна без регистрации.\n2. Правовое основание обработки определено; где нужно согласие, оно оформлено отдельно и без заранее выбранной галочки.\n3. Рекламные сообщения имеют отдельное основание и подтверждение согласия.\n4. Известны состав полей, цели и сроки хранения.\n5. Подтверждены расположение баз и внешние передачи.\n6. Известны оператор, ответственный и контакты.\n7. Описаны запрос данных, отзыв согласия и уничтожение.\n8. Проверены аналитика, логи, cookies и их состав.\n9. Проверены уведомления и сведения в реестре регулятора.\n\nУ интерфейсной или кодовой находки покажи файл и строку. Договоры, реестр и географию сервера не выводи из названия библиотеки. Для пробела предложи действие, документ или техническую правку, указав вопрос для специалиста. Не объявляй сайт законным по результату чтения кода. Итог — рабочий перечень для юриста.\n```","copy_text":"Составь фактическую проверку сайта [адрес или проект] по вопросам обработки персональных данных. Сначала установи юрисдикцию и применимость требований. Для правовых выводов используй действующие официальные источники с датой проверки.\n\nПо девяти пунктам укажи: есть; отсутствует; неприменимо с обоснованием; проверить невозможно по доступным данным.\n1. Публичная политика доступна без регистрации.\n2. Правовое основание обработки определено; где нужно согласие, оно оформлено отдельно и без заранее выбранной галочки.\n3. Рекламные сообщения имеют отдельное основание и подтверждение согласия.\n4. Известны состав полей, цели и сроки хранения.\n5. Подтверждены расположение баз и внешние передачи.\n6. Известны оператор, ответственный и контакты.\n7. Описаны запрос данных, отзыв согласия и уничтожение.\n8. Проверены аналитика, логи, cookies и их состав.\n9. Проверены уведомления и сведения в реестре регулятора.\n\nУ интерфейсной или кодовой находки покажи файл и строку. Договоры, реестр и географию сервера не выводи из названия библиотеки. Для пробела предложи действие, документ или техническую правку, указав вопрос для специалиста. Не объявляй сайт законным по результату чтения кода. Итог — рабочий перечень для юриста.","cover_url":null,"minutes":3,"xp":30,"quiz":[],"published":true,"kind":"lesson","emoji":"⚖️","gradient":"aurora","video_url":null,"pinned":false,"position":31,"free_preview":false,"course_key":null},{"key":"feed-32","source_index":32,"source_type":"prompt","title":"Завершение сессии разработки","category":"Промпты","subtitle":"Проверить изменения и сохранить полезные договорённости","body":"Проверить изменения и сохранить полезные договорённости. Подставь свои данные в квадратные скобки и передай запрос агенту.\n\n```text\nПодведи итог текущей сессии и приведи её изменения в проверяемое состояние.\n\n1. Просмотри diff и найди регрессии, конфликты и ошибки, появившиеся в этой работе. Исправь подтверждённые проблемы в её пределах.\n2. Перечисли оставшиеся TODO, временный код, непроверенные сценарии и нужные тесты.\n3. Сверь отчёт с фактическими сбоями: упавшие проверки, неверные предположения и обходные решения.\n4. Удали созданный в этой сессии неиспользуемый код после проверки ссылок. Не затрагивай чужую незавершённую работу.\n5. Оцени безопасность и производительность изменённых путей. Для расширения объёма объясни причину.\n6. Опиши состояние веток и неслитой работы; не удаляй ветки автоматически.\n7. Сохрани в правилах только устойчивые выводы из этой сессии. Узкие правила держи в тематических файлах.\n8. Отметь, какая процедура, проверка, навык или интеграция могла предотвратить реальные проблемы. Если ничего не требуется, так и напиши.\n\nВ конце коротко опиши текущее состояние, сделанные изменения, риски, обновлённые правила, проверки и следующий шаг. Для неприменимого пункта укажи это; дополнительные задачи не придумывай.\n```","copy_text":"Подведи итог текущей сессии и приведи её изменения в проверяемое состояние.\n\n1. Просмотри diff и найди регрессии, конфликты и ошибки, появившиеся в этой работе. Исправь подтверждённые проблемы в её пределах.\n2. Перечисли оставшиеся TODO, временный код, непроверенные сценарии и нужные тесты.\n3. Сверь отчёт с фактическими сбоями: упавшие проверки, неверные предположения и обходные решения.\n4. Удали созданный в этой сессии неиспользуемый код после проверки ссылок. Не затрагивай чужую незавершённую работу.\n5. Оцени безопасность и производительность изменённых путей. Для расширения объёма объясни причину.\n6. Опиши состояние веток и неслитой работы; не удаляй ветки автоматически.\n7. Сохрани в правилах только устойчивые выводы из этой сессии. Узкие правила держи в тематических файлах.\n8. Отметь, какая процедура, проверка, навык или интеграция могла предотвратить реальные проблемы. Если ничего не требуется, так и напиши.\n\nВ конце коротко опиши текущее состояние, сделанные изменения, риски, обновлённые правила, проверки и следующий шаг. Для неприменимого пункта укажи это; дополнительные задачи не придумывай.","cover_url":null,"minutes":3,"xp":30,"quiz":[],"published":true,"kind":"lesson","emoji":"💬","gradient":"sunset","video_url":null,"pinned":false,"position":32,"free_preview":false,"course_key":null},{"key":"feed-33","source_index":33,"source_title":"Избавляемся от нейротекстов","source_type":"guide","title":"Как редактировать текст после нейросети","category":"Маркетинг","subtitle":"Текст выдаёт себя общими формулировками, одинаковым ритмом и обещаниями без содержания. Полезнее проверять устройство текста целиком, чем охотиться за одним запрещённым словом.","body":"Текст выдаёт себя общими формулировками, одинаковым ритмом и обещаниями без содержания. Полезнее проверять устройство текста целиком, чем охотиться за одним запрещённым словом.\n\n## Десять признаков, которые стоит проверить\n\n1. **Искусственное противопоставление.** Сначала автор называет неподходящее определение, затем исправляет его. Сформулируй мысль прямо.\n2. **Канцелярские конструкции.** «Произвести оплату» можно заменить на «оплатить». Верни действия глаголам и разорви цепочки существительных.\n3. **Клише.** Фразы о современном мире и необходимости что-то отметить занимают место без новой информации.\n4. **Абстракции.** Для эффективности, роста и трансформации назови измеримый результат или конкретное действие.\n5. **Пустые переходы.** Начинай абзац с содержания. Связку оставляй там, где она действительно объясняет связь мыслей.\n6. **Шаблонная концовка.** Вместо призыва «время действовать» назови следующий шаг, если он нужен читателю.\n7. **Неопределённые оговорки.** У утверждения есть условие — напиши это условие. Ограничение знания тоже обозначай конкретно.\n8. **Раздутый заголовок.** Заголовок обещает то, что материал действительно объясняет; обещание революции не заменяет предмет.\n9. **Вступление без фактов.** Убирай строки, после удаления которых содержание не меняется.\n10. **Однообразный тон.** Чередуй длину предложений по смыслу, добавляй проверяемые примеры и собственную позицию.\n\nМеханика канцелярита подробно разобрана Норой Галь в книге «Слово живое и мёртвое»: действие исчезает за существительным, а речь становится неподвижной.\n\n## Инструменты редактора\n\n[humanizer-ru](https://github.com/ilyautov/humanizer-ru) предлагает набор правил для агента. В исходной публикации автор набора заявляет 54 признака в двенадцати категориях. Эти числа описывают состав правил; независимую эффективность они не подтверждают. Прочитай SKILL.md до подключения: правила получат весь переданный текст.\n\n[Главред](https://glvrd.ru/) помогает найти клише, канцелярит и размытые слова. Его оценка показывает долю отмеченных конструкций, а качество аргумента и точность фактов требуют отдельной проверки. Высокий балл не гарантирует полезного текста. Условия веб-проверки и API смотри на сайте.\n\nДля механических линтеров Vale, textlint и proselint важно наличие подходящих русских правил. Не делай вывод об их наличии по одному упоминанию инструмента: проверь конкретный набор и примеры срабатывания.\n\n## Рабочая последовательность\n\nСохрани редакторские правила в проекте, чтобы они не зависели от нового чата. После черновика запусти проверку, исправь конкретные находки, затем вычитай текст глазами. Проследи, не потерялись ли смысл, оговорки и голос автора. Возвращайся к правилам раз в несколько месяцев: модные маркеры быстро меняются.\n\n## Запрос для редактуры\n\n```text\nОтредактируй текст для живого чтения. Сохрани факты, примеры, ограничения и смысл. Убери пустые вступления, клише и канцелярит; абстракции замени конкретикой там, где она есть в исходнике. Новые цифры не придумывай. После текста перечисли только изменения, влияющие на смысл, и вопросы к непроверенным утверждениям.\n```\n\nВ конце спроси себя: понятно ли, о чём материал, есть ли в каждом абзаце новая мысль и подтверждается ли главное обещание?","cover_url":null,"minutes":3,"xp":60,"copy_text":null,"quiz":[],"published":true,"kind":"lesson","emoji":"📣","gradient":"mint","video_url":null,"pinned":false,"position":33,"free_preview":false,"course_key":null},{"key":"feed-34","source_index":34,"source_title":"Лиды без слива бюджета","source_type":"guide","title":"Как построить прямую работу с лидами","category":"Маркетинг","subtitle":"Прямые касания через мессенджер, почту и звонок можно проверить без большого рекламного бюджета. Результат зависит от того, насколько точно выбрана аудитория, понятно предложение и есть разрешение связаться с адресатом.","body":"Прямые касания через мессенджер, почту и звонок можно проверить без большого рекламного бюджета. Результат зависит от того, насколько точно выбрана аудитория, понятно предложение и есть разрешение связаться с адресатом.\n\n## Сначала сегмент и база\n\n[Контур.Поиск клиентов](https://kontur.ru/compass) помогает выбрать организации по отрасли и событиям. В исходной статье перечислены вакансии, сертификаты и изменение адреса: такие сигналы подсказывают актуальную задачу компании. Число источников, фильтров и условия выгрузки проверяй в своём тарифе.\n\nЗапиши гипотезу: кому нужен продукт, почему сейчас и какой результат он даст. Затем отбирай компании. Сам факт наличия публичного контакта не заменяет согласия на рекламу.\n\n## Мессенджеры\n\nTelegram-бот начинает коммуникацию с людьми, которые сами открыли его или разрешили сообщения. [Radist.Online](https://radist.online/) помогает работать с диалогами и рассылками. Перед запуском проверь правила площадки, поддержку нужного канала и способ сохранения согласия. Массовые личные сообщения с обычного аккаунта создают риск жалоб и блокировки.\n\nСостояние WhatsApp и МАКС зависит от правил и доступности сервисов. Исходная статья описывает ситуацию на август 2026 года; её технические ограничения нужно сверять перед новой кампанией.\n\n## Электронная почта\n\nУ рассылочных сервисов есть требования к происхождению базы и подтверждению согласия. Покупка адресов не даёт автоматически права рассылать рекламу. [Coldy](https://coldy.email/) упомянут как инструмент работы с ящиками и последовательностями. Прогрев и постепенное увеличение объёма помогают доставляемости, но не отменяют правовые требования.\n\nПервое письмо посвящай одной задаче адресата. Объясни предложение коротко и задай один понятный вопрос. Не перегружай его вложениями и картинками.\n\n## Звонки\n\nПосчитай стоимость рабочего времени, недозвонов, квалификации и передачи заинтересованного человека менеджеру. При аутсорсе проверь сценарий, качество записей и условия обработки данных. Отдельно проверь законность выбранного способа набора и рекламной коммуникации: наличие оператора само по себе не снимает требования к согласию.\n\n## Цепочка касаний\n\nПодготовь всю последовательность до первого запуска:\n\n1. Объяснение, почему обращаешься, и один вопрос.\n2. Полезный пример или разбор задачи из отрасли.\n3. Конкретное предложение и понятная стоимость либо диапазон.\n4. Аккуратное напоминание.\n5. Завершение ветки с возможностью отказаться от сообщений.\n\nВ исходном сценарии между касаниями предлагается два–три дня. Для своей аудитории выбери частоту, которая не превращает разговор в давление. После отказа отправку прекращай.\n\n## Проверка гипотезы\n\nРаздели небольшую выборку на сопоставимые группы и проверь два первых сообщения. Считай ответы, квалифицированные лиды и продажи. Разница в два ответа на небольшой базе может быть случайной; двести отправок на вариант из исходника — ориентир, а достаточный размер зависит от ожидаемого эффекта.\n\nСравни полную стоимость: база, инструмент, работа, подготовка текста, прогрев и повторные касания. Тарифы статьи относятся к августу 2026 года и не являются текущим прайсом. Оставь время на весь цикл ответов, а не делай вывод после первого дня.\n\n## До старта\n\n- У каждого сегмента есть объяснимая потребность.\n- Согласия и источник контактов зафиксированы.\n- Последовательность написана целиком.\n- Есть простой отказ от последующих сообщений.\n- Замеряются отклик и продажи, а не только открытия.\n- Стоимость лида включает все расходы.\n\nДля рекламы по сетям связи заранее проверь применимые требования статьи 18 закона о рекламе и хранение подтверждений согласия. [Официальная информация ФАС](https://fas.gov.ru/) поможет найти правила для своего способа коммуникации.","cover_url":null,"minutes":3,"xp":60,"copy_text":null,"quiz":[],"published":true,"kind":"lesson","emoji":"📣","gradient":"ocean","video_url":null,"pinned":false,"position":34,"free_preview":false,"course_key":null},{"key":"feed-35","source_index":35,"source_title":"Контент-заводы","source_type":"guide","title":"Контент-конвейер: устройство, расходы и проверка результата","category":"Маркетинг","subtitle":"Контент-конвейер ускоряет повторяемые этапы производства роликов. Его экономика складывается из качества материала, затрат на выпуск и способа превращения внимания в доход. Само число опубликованных видео не доказывает прибыль.","body":"Контент-конвейер ускоряет повторяемые этапы производства роликов. Его экономика складывается из качества материала, затрат на выпуск и способа превращения внимания в доход. Само число опубликованных видео не доказывает прибыль.\n\n## Два типа процесса\n\nПервый перерабатывает длинный материал: расшифровка, выбор фрагментов, вертикальный монтаж, субтитры. Второй создаёт выпуск по сценарию: исследование, текст, голос, изображения, видео и сборка. Анализ удачных роликов помогает изучить хук, темп и кадры, но копирование чужого материала требует прав.\n\n## Оркестратор\n\nСлой управления связывает сервисы и хранит состояние задач. В исходной подборке — n8n, Make, Pipedream и Activepieces. У них разные единицы тарификации: выполнение сценария, отдельная операция, время и ресурсы. На длинной цепочке это влияет на себестоимость.\n\nПосчитай один реальный путь со всеми повторами. Self-hosting добавляет администрирование, обновления, резервирование и стоимость сервера, даже когда лицензия не требует оплаты.\n\n## Слои производства\n\nЯзыковая модель готовит текст и запросы к другим инструментам. Отдельные сервисы отвечают за изображения, озвучку и видео. Remotion или FFmpeg собирает медиадорожки и субтитры. Существующие материалы используй повторно, когда их лицензия и качество подходят.\n\nДля каждого этапа запиши единицу расхода: токены, изображения, символы речи, секунды видео или рендеры. Кэширование повторяющегося контекста может уменьшать стоимость текста. Размер и качество изображения также меняют цену.\n\n## Почему видео дороже\n\nВ таблице исходной статьи на 15 августа 2026 года секунды генерации колебались от $0,05 у Sora 2 до $0,682 у Seedance 2.0 в 1080p. Это исторический пример, а не прайс для покупки. Перед расчётом сверь тариф выбранного провайдера, разрешение, звук и правила оплаты неудачных запусков.\n\nСтоимость принятого кадра включает все неудачные попытки. Если одна сцена потребовала четыре генерации, её себестоимость нельзя записывать как один запрос. Иногда движение из статичных картинок решает задачу значительно дешевле полного генеративного видео.\n\n## Расчёт выпуска\n\n```text\nСебестоимость принятого ролика =\nтекст + изображения + голос + видео + рендер +\nповторные попытки + инфраструктура + труд на проверку.\n```\n\nВ исходном примере ролик из статики оценён примерно в $0,40, а дорогая генеративная сборка — в $30 и выше. Разница иллюстрирует выбор производственного подхода; воспроизвести эти суммы без исходных настроек нельзя.\n\n[Условия Remotion](https://www.remotion.pro/license) разделяют бесплатную и корпоративную лицензии. Для отдельного человека и небольшой команды может подходить бесплатная; состав участников проекта тоже имеет значение. У FFmpeg условия зависят от сборки и включённых компонентов, поэтому проверяют конкретный дистрибутив.\n\n## Как читать обещания дохода\n\nНакопленные просмотры, годовая оценка рекламного дохода и подтверждённая выручка — разные показатели. В исходнике разобран отчёт Kapwing за ноябрь 2025 года с оценками Social Blade. Калькулятор дохода не является выпиской по выплатам. Проверяй период, географию аудитории, формат видео и метод расчёта.\n\nПример автора, рассказавшего о нескольких тысячах долларов за месяц, может быть полезен для изучения процесса, но не обещает такой доход следующему каналу. Исследования доли ИИ-текстов и числа новостных ферм тоже описывают свои выборки, а не личную экономику проекта.\n\n## Правила площадок\n\nYouTube проверяет оригинальность и ценность материала; массовый шаблонный контент может не соответствовать требованиям монетизации. До запуска прочитай действующие [правила монетизации](https://support.google.com/youtube/answer/1311392). Доход Shorts зависит от механики распределения, музыки и вовлечённых просмотров, поэтому одна универсальная ставка вводит в заблуждение.\n\n## Рабочий запуск\n\nСобери один небольшой выпуск вручную, измерь расходы и время проверки, затем автоматизируй устойчивые этапы. Возвращай статистику в процесс: принятые сцены, цена выпуска, удержание, переходы и продажи. У продажи шаблонов и инструментов своя экономика; её нельзя подменять доходом от самих роликов.","cover_url":null,"minutes":3,"xp":60,"copy_text":null,"quiz":[],"published":true,"kind":"lesson","emoji":"📣","gradient":"candy","video_url":null,"pinned":false,"position":35,"free_preview":false,"course_key":null},{"key":"feed-36","source_index":36,"source_title":"Домены до 1 сентября","source_type":"guide","title":"Домены .ru, .рф и .su: идентификация администратора","category":"Закон","subtitle":"Исходная статья опубликована до 1 сентября 2026 года. Дата уже прошла, поэтому прежний призыв успеть заранее заменён проверкой текущего состояния домена. Юридические детали и порядок конкретных операций нужно сверять с регистратором.","body":"Исходная статья опубликована до 1 сентября 2026 года. Дата уже прошла, поэтому прежний призыв успеть заранее заменён проверкой текущего состояния домена. Юридические детали и порядок конкретных операций нужно сверять с регистратором.\n\n## Что изменилось\n\nЗакон № 569-ФЗ от 29 декабря 2025 года вводит идентификацию через ЕСИА для регистрации доменных имён. [Координационный центр](https://cctld.ru/help/faq/) разъясняет применение правил к доменам .ru, .рф и .su и операции с ними. Проверку проходит настоящий администратор домена либо уполномоченный представитель организации по процедуре регистратора.\n\n## Личный срок\n\nСначала выясни дату окончания регистрации. Дата введения нормы и дата продления твоего домена — разные события. Не жди последнего дня: расхождения в ФИО, документах или данных организации могут потребовать ручной проверки.\n\nВ исходнике приведён исторический замер на конец апреля 2026 года: идентификацию прошли около 103,6 тысячи администраторов. Это иллюстрировало риск очередей в поддержке, но не описывает сегодняшнюю готовность владельцев.\n\n## Операции и последствия\n\nПроверь, какие действия твой регистратор связывает с идентификацией: регистрация, продление, смена администратора и перенос. Отдельно уточни правила изменения DNS. Не переноси один ответ о регистрации автоматически на все операции.\n\nИстечение срока, прекращение делегирования и освобождение имени происходят по правилам соответствующей зоны. Заблаговременно выясни период преимущественного продления и возможность восстановления у регистратора. Действующий сайт не доказывает, что ближайшее продление уже доступно.\n\n## Кто особенно рискует\n\n- Домен записан на уволившегося сотрудника.\n- Компания использует домен, оформленный на физическое лицо.\n- Клиентский адрес принадлежит агентству или подрядчику.\n- Панель и административная почта давно не проверялись.\n- Срок регистрации близок к окончанию.\n\nПри смене владельца могут потребоваться действия обеих сторон. Составь план с текущим администратором до того, как доступ к его контактам исчезнет.\n\n## Что подготовить\n\nНайди в панели настоящие сведения администратора, дату окончания и контактную почту. Сверь их с подтверждённой учётной записью Госуслуг или профилем организации. Для нерезидентов порядок подтверждения и доступность документов уточняй отдельно.\n\nПереходи к идентификации из панели своего регистратора. Проверь адрес страницы и состав запрашиваемых данных. По завершении сохрани результат и убедись, что статус изменился именно у нужного домена.\n\n## Проверка портфеля доменов\n\nСделай таблицу: домен, зона, регистратор, администратор, дата окончания, рабочая почта, статус идентификации и ответственное лицо. У корпоративного домена должны быть понятные права владения и восстановимый доступ к панели. Настрой напоминание о продлении и проверь платёжный способ.\n\nЭтот материал — ориентир для проверки. Актуальные операции и сроки определяются действующими правилами зоны и регистратора.","cover_url":null,"minutes":3,"xp":60,"copy_text":null,"quiz":[],"published":true,"kind":"lesson","emoji":"⚖️","gradient":"lime","video_url":null,"pinned":false,"position":36,"free_preview":false,"course_key":null},{"key":"feed-37","source_index":37,"source_type":"prompt","title":"Storybook для своего проекта","category":"Дизайн","subtitle":"Витрина компонентов с настоящими стилями и шириной экрана","body":"Витрина компонентов с настоящими стилями и шириной экрана. Подставь свои данные в квадратные скобки и передай запрос агенту.\n\n```text\nПодключи Storybook к моему проекту [стек, например React + Vite]. Сначала прочитай package.json и выясни подходящую версию и официальный способ интеграции.\n\nИщи истории в src/**/*.stories.tsx. Подключи в preview стили и шрифты приложения, чтобы витрина использовала реальные токены. Добавь состояния обычного компонента, загрузки, пустого результата и ошибки там, где они применимы.\n\nПорт передавай снаружи команды запуска: сначала проверь, какой свободен. Задай порядок разделов: токены, компоненты, экраны, решения. Для мобильных экранов используй контейнер шириной [390] пикселей и проверь также другую ширину.\n\nУстанови только необходимые пакеты, дополнительные аддоны обоснуй отдельно. После настройки запусти витрину, открой реальные истории и проверь, что подключены тема, шрифты и состояния. Покажи адрес, результат сборки и снимок открытой истории.\n```","copy_text":"Подключи Storybook к моему проекту [стек, например React + Vite]. Сначала прочитай package.json и выясни подходящую версию и официальный способ интеграции.\n\nИщи истории в src/**/*.stories.tsx. Подключи в preview стили и шрифты приложения, чтобы витрина использовала реальные токены. Добавь состояния обычного компонента, загрузки, пустого результата и ошибки там, где они применимы.\n\nПорт передавай снаружи команды запуска: сначала проверь, какой свободен. Задай порядок разделов: токены, компоненты, экраны, решения. Для мобильных экранов используй контейнер шириной [390] пикселей и проверь также другую ширину.\n\nУстанови только необходимые пакеты, дополнительные аддоны обоснуй отдельно. После настройки запусти витрину, открой реальные истории и проверь, что подключены тема, шрифты и состояния. Покажи адрес, результат сборки и снимок открытой истории.","cover_url":null,"minutes":3,"xp":30,"quiz":[],"published":true,"kind":"lesson","emoji":"🎨","gradient":"aurora","video_url":null,"pinned":false,"position":37,"free_preview":false,"course_key":null},{"key":"feed-38","source_index":38,"source_type":"prompt","title":"Разбор решения и скрытых издержек","category":"Промпты","subtitle":"Сравнить варианты и выбрать один с учётом рисков","body":"Сравнить варианты и выбрать один с учётом рисков. Подставь свои данные в квадратные скобки и передай запрос агенту.\n\n```text\nМне нужно принять решение: [суть]. Ограничения: [время], [деньги], [обязательные условия].\n\nСначала сформулируй задачу своими словами и отметь существенные неизвестные. Предложи три–пять выполнимых вариантов. Для каждого сравни пользу, недостатки, скрытые затраты, зависимость от внешних условий и возможность отменить решение.\n\nРекомендуй один вариант и объясни, почему он лучше подходит под эти ограничения. Если данных недостаточно, назови небольшую проверку, которая позволит выбрать. В конце укажи три наиболее вероятных сбоя и действия на случай каждого. Не подменяй факты уверенностью формулировки.\n```","copy_text":"Мне нужно принять решение: [суть]. Ограничения: [время], [деньги], [обязательные условия].\n\nСначала сформулируй задачу своими словами и отметь существенные неизвестные. Предложи три–пять выполнимых вариантов. Для каждого сравни пользу, недостатки, скрытые затраты, зависимость от внешних условий и возможность отменить решение.\n\nРекомендуй один вариант и объясни, почему он лучше подходит под эти ограничения. Если данных недостаточно, назови небольшую проверку, которая позволит выбрать. В конце укажи три наиболее вероятных сбоя и действия на случай каждого. Не подменяй факты уверенностью формулировки.","cover_url":null,"minutes":3,"xp":30,"quiz":[],"published":true,"kind":"lesson","emoji":"💬","gradient":"sunset","video_url":null,"pinned":false,"position":38,"free_preview":false,"course_key":null},{"key":"feed-39","source_index":39,"source_type":"prompt","title":"Разработка с двумя независимыми проверками","category":"Промпты","subtitle":"Один агент меняет код, два проверяют результат","body":"Один агент меняет код, два проверяют результат. Подставь свои данные в квадратные скобки и передай запрос агенту.\n\n```text\nОрганизуй работу трёх агентов над задачей [функция и критерий готовности].\n\nПервый реализует задачу и показывает изменения и проверки. Второй читает diff и оценивает корректность, простоту и риски по шкале 1–10. Для замечания нужны файл, строка и конкретное последствие. Третий проверяет рассуждения второго, ищет пропущенные проблемы и отбрасывает замечания без существенного эффекта; выставляет свои три оценки.\n\nПроверяющие не редактируют код. Для следующего круга они получают текущую задачу и diff без прежних оценок. Оценка круга — минимум шести значений. Если она ниже девяти, первый исправляет подтверждённые замечания и повторяет подходящие проверки.\n\nОценку девять или выше обоснуй выполненными сценариями и проверками. После пяти кругов остановись и сообщи, что препятствует завершению. Проверяй фактические критерии готовности: высокий балл сам по себе не заменяет тест и работающий результат.\n```","copy_text":"Организуй работу трёх агентов над задачей [функция и критерий готовности].\n\nПервый реализует задачу и показывает изменения и проверки. Второй читает diff и оценивает корректность, простоту и риски по шкале 1–10. Для замечания нужны файл, строка и конкретное последствие. Третий проверяет рассуждения второго, ищет пропущенные проблемы и отбрасывает замечания без существенного эффекта; выставляет свои три оценки.\n\nПроверяющие не редактируют код. Для следующего круга они получают текущую задачу и diff без прежних оценок. Оценка круга — минимум шести значений. Если она ниже девяти, первый исправляет подтверждённые замечания и повторяет подходящие проверки.\n\nОценку девять или выше обоснуй выполненными сценариями и проверками. После пяти кругов остановись и сообщи, что препятствует завершению. Проверяй фактические критерии готовности: высокий балл сам по себе не заменяет тест и работающий результат.","cover_url":null,"minutes":3,"xp":30,"quiz":[],"published":true,"kind":"lesson","emoji":"💬","gradient":"mint","video_url":null,"pinned":false,"position":39,"free_preview":false,"course_key":null},{"key":"feed-40","source_index":40,"source_type":"tool","title":"Genery: кадры для своей раскадровки","category":"Видео","subtitle":"Кадры известных фильмов в Genery собраны по визуальным приёмам, включая монтаж и движение камеры.","cover_url":"https://proninlearn.ru/posts/genery-604w.webp","minutes":2,"xp":20,"body":"Кадры известных фильмов в Genery собраны по визуальным приёмам, включая монтаж и движение камеры. Когда планируешь сцену, найди нужный тип кадра и объясни агенту, какую функцию он выполняет. Свою раскадровку собирай под содержание ролика, а референс используй для композиции и темпа.\n\n## Открыть ресурс\n\n- [genery.io](https://genery.io/)","copy_text":null,"quiz":[],"published":true,"kind":"lesson","emoji":"🎬","gradient":"ocean","video_url":null,"pinned":false,"position":40,"free_preview":false,"course_key":null},{"key":"feed-41","source_index":41,"source_type":"tool","title":"Geometric Shots: видеть композицию кадра","category":"Видео","subtitle":"Разметка поверх кинокадров показывает горизонт, симметрию и точки схода.","cover_url":"https://proninlearn.ru/posts/geometric-604w.webp","minutes":2,"xp":20,"body":"Разметка поверх кинокадров показывает горизонт, симметрию и точки схода. По таким примерам проще понять, почему объект стоит именно там и куда идёт взгляд зрителя. Прежде чем собирать свой кадр, наметь главное, свободное место для текста и линию движения.\n\n## Открыть ресурс\n\n- [geometricshots.tumblr.com](https://geometricshots.tumblr.com/)","copy_text":null,"quiz":[],"published":true,"kind":"lesson","emoji":"🎬","gradient":"candy","video_url":null,"pinned":false,"position":41,"free_preview":false,"course_key":null},{"key":"feed-42","source_index":42,"source_type":"tool","title":"База Uprock: ассеты по разделам","category":"Дизайн","subtitle":"В базе Uprock собраны 3D, шрифты, мокапы и другие материалы для дизайна.","cover_url":"https://proninlearn.ru/posts/uprock-604w.webp","minutes":2,"xp":20,"body":"В базе Uprock собраны 3D, шрифты, мокапы и другие материалы для дизайна. Категории помогают быстро найти подходящий тип ресурса. Условия использования проверяй у конкретного файла: наличие в бесплатной подборке само по себе не объясняет лицензию на коммерческий проект.\n\n## Открыть ресурс\n\n- [baza.uprock.ru](https://baza.uprock.ru/)","copy_text":null,"quiz":[],"published":true,"kind":"lesson","emoji":"🎨","gradient":"lime","video_url":null,"pinned":false,"position":42,"free_preview":false,"course_key":null},{"key":"feed-43","source_index":43,"source_type":"tool","title":"AppRoute: инфраструктура цифровых товаров","category":"Прочее","subtitle":"AppRoute представлен в подборке как поставщик для магазина цифровых товаров.","cover_url":"https://proninlearn.ru/posts/approute-604w.webp","minutes":2,"xp":20,"body":"AppRoute представлен в подборке как поставщик для магазина цифровых товаров. Если рассматриваешь такой проект, сначала уточни ассортимент, правила выдачи, возвратов и поддержку покупателей. Затем проверь всю цепочку на тестовом заказе, включая то, как исправляются неуспешные доставки.\n\n## Открыть ресурс\n\n- [approute.ru](https://approute.ru/)","copy_text":null,"quiz":[],"published":true,"kind":"lesson","emoji":"🧰","gradient":"aurora","video_url":null,"pinned":false,"position":43,"free_preview":false,"course_key":null},{"key":"feed-44","source_index":44,"source_type":"tool","title":"Replicate: модели через единый API","category":"Прочее","subtitle":"Replicate даёт программный доступ к различным моделям.","cover_url":"https://proninlearn.ru/posts/replicate-604w.webp","minutes":2,"xp":20,"body":"Replicate даёт программный доступ к различным моделям. Его можно включить в конвейер для картинок, видео и других задач, когда нужно вызывать сервис из кода. У каждой модели свои параметры, стоимость и лицензия; сначала проверь один небольшой запуск и обработку ошибки.\n\n## Открыть ресурс\n\n- [replicate.com](https://replicate.com/)","copy_text":null,"quiz":[],"published":true,"kind":"lesson","emoji":"🧰","gradient":"sunset","video_url":null,"pinned":false,"position":44,"free_preview":false,"course_key":null},{"key":"feed-45","source_index":45,"source_type":"tool","title":"Appica UI: компоненты с доступностью","category":"Дизайн","subtitle":"Appica UI — библиотека React-компонентов; в подборке указано больше семидесяти элементов.","cover_url":"https://proninlearn.ru/posts/appica-604w.webp","minutes":2,"xp":20,"body":"Appica UI — библиотека React-компонентов; в подборке указано больше семидесяти элементов. В компонентах предусмотрена работа клавиатуры и экранного диктора. При адаптации сохрани эти сценарии: фокус должен оставаться видимым, подписи понятными, а управление — доступным без мыши.\n\n## Открыть ресурс\n\n- [appica.dev](https://appica.dev/)","copy_text":null,"quiz":[],"published":true,"kind":"lesson","emoji":"🎨","gradient":"mint","video_url":null,"pinned":false,"position":45,"free_preview":false,"course_key":null},{"key":"feed-46","source_index":46,"source_title":"Как работать с памятью в Клоде","source_type":"guide","title":"Память Claude Code: правила, навыки и хуки","category":"Нейронки","subtitle":"Повторяющиеся объяснения лучше переносить из чата в файлы проекта. Агент получает контекст из загруженных инструкций и памяти; это не означает, что он постоянно учится на всём проекте или гарантированно выполняет каждое правило.","body":"Повторяющиеся объяснения лучше переносить из чата в файлы проекта. Агент получает контекст из загруженных инструкций и памяти; это не означает, что он постоянно учится на всём проекте или гарантированно выполняет каждое правило.\n\n## Личная и проектная область\n\n```text\n~/.claude/\n  CLAUDE.md       личные инструкции\n  rules/          личные правила\n  projects/       память проектов\n\nmy-app/\n  CLAUDE.md       общие инструкции команды\n  CLAUDE.local.md локальные предпочтения\n  .claude/\n    rules/        тематические правила\n    skills/       процедуры\n    settings.json настройки, включая хуки\n```\n\nДомашняя папка задаёт общие привычки. Правила внутри проекта описывают его команды, архитектуру, оформление и известные особенности. Так настройки одного продукта не подменяют дизайн соседнего.\n\n## Основной файл правил\n\nВ CLAUDE.md оставь команды запуска и проверки, важные ограничения и особенности, которые нельзя вывести из кода. Например, занятый порт Storybook или требование локального Redis. Личную настройку, которую команда не должна получать, держи отдельно и проверь .gitignore.\n\nПравила должны согласовываться между собой. Удали строку, если без неё агент не начнёт ошибаться. Указанные в исходной статье двести строк для основного файла — рекомендация по ясности, а не универсальный технический предел.\n\n## Тематические правила\n\nДизайн, база и тесты могут лежать в разных файлах .claude/rules. Маски paths помогают привязать правило к нужной части проекта. Например, `src/**/*.tsx` относится к React-файлам. Правила, необходимые при создании нового компонента, должны загружаться и до чтения существующего файла; проверь механизм своей версии Claude Code.\n\n## Навыки\n\nПроцедура хранится в папке с SKILL.md. Имя и описание помогают агенту определить, когда читать полные инструкции. Конкретное описание связывает навык с понятной просьбой: подготовка релиза, разбор инцидента, экспорт документа. Общие требования к каждому компоненту обычно удобнее хранить как правила.\n\n## Хуки\n\nХук запускает команду на событии инструмента. Например, после изменения файла может запускаться линтер. Это программная проверка; текстовая просьба выполнить линтер остаётся инструкцией модели. Для запрета записи нужен подходящий момент проверки, поэтому один PostToolUse не отменяет уже выполненную запись.\n\nУчитывай рабочую папку и корректно передавай путь к скрипту. Проверь хук отдельным тестовым действием, его код выхода и результат отказа. Скрипт должен существовать и быть безопасным; пример настройки без самого скрипта не даёт работающей защиты.\n\n## Автоматическая память\n\nПопроси сохранить конкретную повторяющуюся особенность проекта. Затем проверь файл и то, что подгрузилось в следующей сессии. У основного индекса памяти может быть ограничение объёма автоматически загружаемой части; длинные подробности раскладывай по отдельным тематическим файлам.\n\n## Настройка с нуля\n\n1. Выполни /init и проверь черновик.\n2. Сократи его до нужных проекту инструкций.\n3. Разнеси тематические правила и процедуры.\n4. Добавь обязательные программные проверки там, где цена пропуска велика.\n5. Посмотри /context: какие файлы действительно доступны агенту.\n6. На новом запуске проверь одну повторявшуюся ошибку.\n\nЗаписывай устойчивые договорённости после повторного объяснения. Секреты и токены в файлы памяти не помещай. Синтаксис своей версии сверяй в [официальной документации](https://code.claude.com/docs/en/memory).","cover_url":null,"minutes":3,"xp":60,"copy_text":null,"quiz":[],"published":true,"kind":"lesson","emoji":"🤖","gradient":"ocean","video_url":null,"pinned":false,"position":46,"free_preview":false,"course_key":null},{"key":"feed-47","source_index":47,"source_title":"Режимы рассуждений: пять уровней","source_type":"guide","title":"Уровень рассуждений: как выбрать усилие агента","category":"Нейронки","subtitle":"Параметр effort влияет на то, насколько тщательно модель работает над задачей. Он связан с расходом и длительностью ответа, но не равен фиксированному числу токенов. Сложная задача может потребовать размышления даже при низком уровне.","body":"Параметр effort влияет на то, насколько тщательно модель работает над задачей. Он связан с расходом и длительностью ответа, но не равен фиксированному числу токенов. Сложная задача может потребовать размышления даже при низком уровне.\n\n## Шкала из исходного материала\n\nСтатья описывает low, medium, high, xhigh и max. Наличие уровней, значение по умолчанию и способ сохранения зависят от модели и версии инструмента. Проверь доступные варианты в текущем /effort или /model и не переноси настройки одной модели на другую автоматически.\n\n- Low подходит для прямой, небольшой задачи с понятной проверкой.\n- Medium позволяет умеренную глубину анализа.\n- High используют, когда нужны дополнительные проверки и связанный контекст.\n- Xhigh и max в поддерживающих их моделях оставляют для задач, где дополнительное усилие окупается.\n\n## Модель и effort\n\nВыбор модели меняет доступные возможности и знание предмета. Effort меняет характер работы выбранной модели. Более высокий уровень не добавляет отсутствующую документацию, тестовые данные или доступ к среде.\n\nСначала дай цель, нужные файлы, ограничения и критерий готовности. Если агент пропустил существенный шаг, выясни, хватало ли контекста, а затем сравни результат на другом уровне.\n\n## Как менять настройку\n\nВ исходной статье перечислены интерактивная команда, выбор модели, параметр запуска, переменная окружения и файл настроек. Порядок приоритетов и допустимые значения нужно сверять с актуальной документацией. Не сохраняй неподдерживаемый уровень, ожидая, что он обязательно применится: инструмент может выбрать другое значение.\n\nВключение самого режима thinking и выбор effort — разные настройки. Текстовая фраза «думай глубже» тоже не является доказательством изменения параметра API. Проверяй фактическую конфигурацию.\n\n## Цена переключения\n\nИзменение параметров может влиять на кэширование контекста. В длинной сессии разумно выбрать уровень заранее, когда задача уже понятна. Но если качество недостаточно, стоимость повторного запроса оценивают вместе с ценой ошибки.\n\nВысокое значение может увеличить количество действий, пояснений и время. Универсальный коэффициент расхода из этого не следует. Измеряй свою задачу: качество принятого результата, количество исправлений, длительность и доступную статистику usage.\n\n## Проверка на своих задачах\n\nВозьми несколько типовых работ с внешней проверкой: тестом, сборкой или сверкой данных. Используй одинаковый контекст и сравни минимум два уровня. Запиши, где уровень ниже дал такой же принятый результат, а где агент действительно пропустил проблему.\n\nОтсутствие видимого блока размышлений не доказывает неисправность. Приложение, работающее с API, должно учитывать разные форматы ответа и сверять доступные поля usage с документацией.\n\n## Чек-лист\n\n- Поддерживаемые уровни текущей модели проверены.\n- Установленный уровень виден в конфигурации.\n- Подъём связан с конкретным недостатком результата.\n- Контекст и критерий готовности заданы до сравнения.\n- Решение основано на замерах, а не на обещании «максимум всегда лучше».\n\n[Официальная документация Claude Code](https://code.claude.com/docs/en/model-config) — источник для актуальных настроек. Перечень моделей и особые значения по умолчанию из исходной статьи здесь не выдаются за текущий список.","cover_url":null,"minutes":3,"xp":60,"copy_text":null,"quiz":[],"published":true,"kind":"lesson","emoji":"🤖","gradient":"candy","video_url":null,"pinned":false,"position":47,"free_preview":false,"course_key":null},{"key":"feed-48","source_index":48,"source_title":"Работаем в Клоде без банов","source_type":"guide","title":"Доступ к Claude: правила, риски и восстановление","category":"Нейронки","subtitle":"Гарантированного способа избежать блокировки нет. Работоспособность чужого аккаунта не доказывает, что его способ использования разрешён. Опирайся на условия провайдера, поддерживаемые регионы и официальный способ доступа.","body":"Гарантированного способа избежать блокировки нет. Работоспособность чужого аккаунта не доказывает, что его способ использования разрешён. Опирайся на условия провайдера, поддерживаемые регионы и официальный способ доступа.\n\n## Что известно, а что предполагается\n\nИсходный материал приводит статистику блокировок и апелляций, рассказы пользователей и исследования антифрода. Статистика без разбивки причин не позволяет вывести личную вероятность бана. Рассказ «меня разблокировали за сутки» не задаёт срок обработки следующих обращений.\n\n## Сеть и история адреса\n\nIP-адрес может использоваться для определения региона и оценки риска. У выделенного адреса есть предыдущие владельцы; соседство по подсети и провайдер тоже могут влиять на репутационные системы. Проверки Spamhaus, AbuseIPDB, Scamalytics, MXToolbox и bgp.he.net помогают изучить разные сигналы, но не дают гарантии принятия сервисом.\n\nПочтовый список блокировки, жалобы на адрес и решение антифрода конкретной платформы — разные системы. «Чисто» в одном списке не означает, что все остальные проверки пройдены. Не используй техническую настройку как основание обходить ограничения региона.\n\n## Браузер и данные профиля\n\nЯзык, часовой пояс, версия движка и характеристики среды могут использоваться для анализа согласованности сессии. Подмена отпечатка иногда создаёт противоречия сама. WebRTC и сетевые параметры отличаются от обычных настроек HTTP-прокси.\n\nВ исходной подборке приведены BrowserLeaks, CreepJS, PixelScan и IPHey. Они показывают отдельные свойства браузера. Их положительный ответ не является решением платформы о допуске аккаунта.\n\nОблачный профиль стороннего браузера может содержать cookies и сессии. Передача такого профиля даёт доступ к аккаунтам. Не загружай рабочие токены в непроверенные приложения и не отключай защиту браузера ради результата теста.\n\n## Оплата\n\nСтрана выпуска карты связана с банковскими данными, а адрес в платёжной форме не меняет её. Биллинг и 3-D Secure могут участвовать в проверке платежа. Используй поддерживаемый способ оплаты и реальные сведения, согласованные с банком. У платёжного посредника отдельные риски; предположение о связанной блокировке нескольких клиентов нельзя считать доказанным правилом.\n\nСверь [поддерживаемые страны](https://www.anthropic.com/supported-countries), условия оплаты и справку об отказах до покупки. Наличие карты не отменяет условия доступа из региона.\n\n## Если доступ заблокирован\n\nОткрой официальный процесс апелляции для заблокированного аккаунта. Коротко укажи факты: кто пользуется аккаунтом, передавался ли доступ, что происходило перед ограничением и какие сообщения получены. Не выдумывай объяснение и не публикуй платёжные данные или токены в публичном трекере.\n\nЕсли пришло письмо о восстановлении, а вход по-прежнему закрыт, ответь в официальном канале с точным описанием. Возврат платежа и сроки рассматривай по условиям конкретного случая.\n\n## Устойчивость рабочего процесса\n\n- Аккаунт и ключи используются по правилам провайдера.\n- Данные доступа не передаются сторонним клиентам без проверки.\n- Важные исходники и договорённости лежат у тебя.\n- Для бизнес-процесса есть запасной способ выполнить работу.\n- Известен официальный путь обращения в поддержку.\n\nАктуальные требования определяет [Anthropic](https://www.anthropic.com/legal/consumer-terms). Этот материал объясняет факторы риска и не обещает «техническое лечение» запрещённого способа доступа.","cover_url":null,"minutes":3,"xp":60,"copy_text":null,"quiz":[],"published":true,"kind":"lesson","emoji":"🤖","gradient":"lime","video_url":null,"pinned":false,"position":48,"free_preview":false,"course_key":null},{"key":"feed-49","source_index":49,"source_title":"С чего начать, если решил вайбкодить","source_type":"guide","title":"Первый проект с ИИ: настройка и привычка проверять","category":"Нейронки","subtitle":"Первый экран можно получить быстро, а устойчивый навык развивается практикой. Главная задача новичка — научиться давать контекст, сохранять рабочее состояние и проверять то, что агент считает готовым.","body":"Первый экран можно получить быстро, а устойчивый навык развивается практикой. Главная задача новичка — научиться давать контекст, сохранять рабочее состояние и проверять то, что агент считает готовым.\n\n## Контекст до работы\n\nОпиши человека, который будет пользоваться результатом, его действие и видимый критерий успеха. Дай агенту пример уже работающего решения и место, с которого начинать. Исследования сессий из исходной статьи сравнивают опытных и новичков, но корреляция длины промпта с успехом не означает, что любой длинный запрос лучше короткого.\n\n## Подготовка\n\nПроверь Node.js и Git, если они нужны стеку. Установи выбранного агента по официальной инструкции и открой отдельную папку маленького проекта. Не используй случайную команду установки из старого поста без сверки версии.\n\n```sh\nnode -v\ngit --version\ngit status\ngit diff\n```\n\nНастрой имя и почту автора коммитов, создай репозиторий и сохрани первую рабочую версию. Эти параметры авторства сами по себе не включают криптографическую подпись коммитов.\n\n## Git до больших правок\n\nstatus показывает список изменений, diff — их содержание. Сохраняй логически законченный шаг коммитом после просмотра файлов. До крупной правки полезно иметь проверенную точку возврата. Команды восстановления могут удалить несохранённую работу, поэтому сначала изучи diff и сохрани нужные изменения.\n\n## Внешняя проверка\n\nУ проекта должна быть команда, которую агент может запустить: сборка, типы или подходящий тест. Для интерфейса добавь просмотр страницы и проверку сценария. Условие «страница открывается» не проверяет вход, ошибки и работу на телефоне.\n\nСложную работу раздели на изучение, план, реализацию и сохранение результата. У небольшой правки эти этапы могут быть короткими. Доказательство готовности — наблюдаемый результат проверки.\n\n## Пять повторяющихся проблем\n\n- Смешанные задачи засоряют контекст: несвязанные работы лучше вести отдельно.\n- Круг исправлений повторяет ошибочную догадку: после двух неудач собери факты и пересмотри постановку.\n- Раздутые правила скрывают главное: оставь требования, которые действительно предотвращают ошибки.\n- Правдоподобная реализация проходит мимо краевых случаев: проверь пустые данные, отказ доступа и сбой сети.\n- Исследование без границ читает всё подряд: укажи область и вопрос, на который нужен ответ.\n\n## Безопасность\n\nРаботающий код может содержать уязвимости. Укажи требования к авторизации, принадлежности объектов, секретам, входным данным и лимитам. Проверь их отдельно от сборки. Исходная статья приводит случаи удаления боевой базы и публичных ключей: оба показывают, почему тестовая среда и резервирование нужны до автономных правок.\n\nСекреты не попадают в репозиторий или клиентский код. Продакшен и тестовые данные разделены. Агенту не нужно давать боевые права для обучения на первом проекте.\n\n## Подходящий старт\n\nВозьми личную страницу, небольшой бот или скрипт с понятным результатом и низкой ценой ошибки. Сначала заверши один сценарий целиком. Затем добавляй функции. Не начинай с чужих персональных данных и настоящих платежей.\n\n## Проверка первой недели\n\nЕсть рабочая папка и репозиторий, сохранён хотя бы один проверенный шаг, просмотрен diff, понятен возврат к предыдущему состоянию. Сборка запускается, правила проекта компактны, секреты исключены из Git, а результат просмотрен глазами. Планируй регулярные часы практики: скорость первого результата и уверенность в работе растут по-разному.\n\n[Практики Claude Code](https://code.claude.com/docs/en/best-practices) помогут сверить актуальный рабочий процесс.","cover_url":null,"minutes":3,"xp":60,"copy_text":null,"quiz":[],"published":true,"kind":"lesson","emoji":"🤖","gradient":"aurora","video_url":null,"pinned":false,"position":49,"free_preview":false,"course_key":null},{"key":"feed-50","source_index":50,"source_title":"Формула идеального промпта","source_type":"guide","title":"Рабочий промпт: цель, контекст, границы и проверка","category":"Нейронки","subtitle":"Пять частей запроса помогают агенту понять задачу и подтвердить результат: цель, место работы, границы, критерий готовности и формат отчёта. Сильный промпт уменьшает догадки и связывает действия с внешней проверкой.","body":"Пять частей запроса помогают агенту понять задачу и подтвердить результат: цель, место работы, границы, критерий готовности и формат отчёта. Сильный промпт уменьшает догадки и связывает действия с внешней проверкой.\n\n## 1. Цель через наблюдаемый симптом\n\nФраза «почини вход» не объясняет, что сломалось. Укажи действие, условие и результат: после истечения сессии повторный вход возвращает ошибку, хотя пароль верен. Так агент ищет конкретный поток, а не выбирает самое вероятное значение слова «баг».\n\n## 2. Место и образец\n\nДай папку, функцию или файл, с которого начинать. Работающий соседний компонент показывает соглашения проекта точнее общего описания стиля. Попроси прочитать образец и назвать, что из него переносится в новый сценарий.\n\n## 3. Границы\n\nНазови затрагиваемую область, допустимые зависимости и условия выхода за рамки. Например, новый маршрут меняет модуль заказов и регистрацию маршрута; остальную архитектуру сохраняют. Если ограничение мешает задаче, агент сначала объясняет причину расширения.\n\n## 4. Критерий готовности\n\nЗадай проверку, доступную инструментам: тест, сборку, измерение времени или сценарий в браузере. Для ускорения API укажи объём данных, процентиль и среду измерения. Для дизайна дай макет и требуй просмотр результата, а не отчёт только о записанном CSS.\n\n## 5. Формат доказательства\n\nВ отчёте нужны изменения, результат проверок и оставшиеся ограничения. Вывод команды или снимок страницы даёт основание оценить готовность. Слова «всё работает» без проверки оставляют эту работу человеку.\n\n## Пример запроса\n\n```text\nПосле истечения сессии повторный вход возвращает ошибку. Начни с src/auth/ и сравни поток обновления токена с работающим тестом входа. Исправь эту причину без новых пакетов и изменений соседних модулей. Проверь воспроизведение, успешный вход и отказ с неверным токеном. Покажи изменённые файлы, результаты проверок и то, что осталось непроверенным. Если понадобится расширить область, объясни причину до правки.\n```\n\n## Что не является универсальным усилителем\n\nПросьба «думай пошагово» помогала некоторым прежним моделям на задачах рассуждения; это не универсальная добавка к современному агенту. Разные исследования показывают зависимость эффекта от задачи и модели. Проси краткое обоснование и проверяемый результат, а не внутреннюю цепочку размышлений.\n\nРоль эксперта может задавать тон и предмет разговора, но не гарантирует точность. Обещание чаевых, угрозы и заглавные буквы тоже не заменяют исходные данные. Агрессивные инструкции могут расширить поведение за пределы нужной задачи.\n\n## Примеры и оформление\n\nНесколько примеров полезны, если задают нужные входы, тон или структуру ответа. Выбирай типовые и краевые случаи, отделяй данные от инструкций. Не смешивай в одном сравнении новое содержание и новую разметку: иначе неясно, что повлияло на результат.\n\nДля длинного контекста выдели релевантные документы, затем сформулируй вопрос и требования. Нужная информация в середине большого массива может использоваться хуже. Порядок и количество материалов проверяй на своих задачах.\n\n## Строгий формат\n\nJSON полезен, когда ответ должен обработать код. Слишком раннее ограничение формы может усложнить задачу. Если нужно, раздели анализ предмета и перевод проверенного результата в схему. Валидный JSON подтверждает форму, а правильность значений проверяется отдельно.\n\n## Самопроверка\n\nПовторное мнение той же модели без новых данных может изменить верный ответ на неверный. Дай внешний сигнал: тест, документ, расчёт или результат команды. Тогда у агента появляется основание исправлять конкретную ошибку.\n\n## Перед отправкой\n\n- В запросе одна задача и видимый симптом.\n- Указаны место начала и полезный образец.\n- Границы понятны, есть правило расширения.\n- Готовность связана с проверкой.\n- Данные отделены от инструкций.\n- Отчёт включает доказательство и ограничения.\n\nИсследовательские цифры исходной статьи относятся к отдельным бенчмаркам. Они не дают единого процента улучшения для твоего проекта.","cover_url":null,"minutes":4,"xp":60,"copy_text":null,"quiz":[],"published":true,"kind":"lesson","emoji":"🤖","gradient":"sunset","video_url":null,"pinned":false,"position":50,"free_preview":false,"course_key":null},{"key":"feed-51","source_index":51,"source_title":"Где лежат деньги в нейронках","source_type":"guide","title":"Что можно продавать тем, кто работает с ИИ","category":"Продукт","subtitle":"Люди, создающие продукты с агентами, сталкиваются с повторяющимися задачами: единый дизайн, устойчивые правила работы, безопасность и документы. Решение такой задачи можно оформить в отдельную услугу или продукт.","body":"Люди, создающие продукты с агентами, сталкиваются с повторяющимися задачами: единый дизайн, устойчивые правила работы, безопасность и документы. Решение такой задачи можно оформить в отдельную услугу или продукт.\n\n## Дизайн-системы\n\nПокупателю полезны согласованные токены, компоненты, адаптивные состояния, инструкции агенту и способ визуальной проверки. Стоимость создаёт поддерживаемая система, которую можно применить к своему продукту и обновлять. Один набор красивых экранов закрывает меньше задач.\n\n## Настройка работы агента\n\nПравила, навыки, хуки, процедуры проверки и интеграции MCP под конкретную отрасль помогают повторять рабочий результат. Покажи, какую ошибку предотвращает каждый элемент, и проверь установку на новом проекте. Упаковка должна включать настройку, документацию и границы ответственности.\n\n## Аудит безопасности\n\nАвтор продукта может не уметь оценить код, даже если умеет получить его от агента. Проверка доступа, секретов и бизнес-операций решает понятную задачу. Результат услуги — подтверждённые находки, приоритеты и проверяемые исправления; обещание полной неуязвимости ненадёжно.\n\n## Подготовка юридической части\n\nОферта, данные пользователей, касса, чеки и возвраты связаны с конкретным бизнесом и юрисдикцией. Здесь нужен специалист, который выяснит реальную деятельность, а не подставит реквизиты в случайный шаблон. Агент может подготовить перечень вопросов и документов.\n\n## Проверка спроса\n\nВыпиши повторяющуюся проблему из своей практики. Найди несколько людей с такой же задачей, предложи ограниченный результат и посмотри, готовы ли они платить. После первых заказов отдели повторяемую часть от индивидуальной работы.\n\nСуществующие рабочие файлы могут стать товаром после проверки прав, документации и воспроизводимости. Расходы людей на подписки не доказывают их готовность купить новый продукт: спрос проверяется конкретным предложением.","cover_url":null,"minutes":3,"xp":60,"copy_text":null,"quiz":[],"published":true,"kind":"lesson","emoji":"💡","gradient":"mint","video_url":null,"pinned":false,"position":51,"free_preview":false,"course_key":null},{"key":"feed-52","source_index":52,"source_title":"Все способы взлома и как закрыть каждый","source_type":"guide","title":"Проверка безопасности по классам рисков","category":"Безопасность","subtitle":"Общая просьба проверить безопасность оставляет агенту выбор предмета. Лучше задать перечень классов, требовать доказательства в коде и разделять чтение проекта, проверку конфигурации и запуск сценариев. Работа проводится в своей системе или в явно разрешённой среде.","body":"Общая просьба проверить безопасность оставляет агенту выбор предмета. Лучше задать перечень классов, требовать доказательства в коде и разделять чтение проекта, проверку конфигурации и запуск сценариев. Работа проводится в своей системе или в явно разрешённой среде.\n\n## OWASP Top 10:2025\n\nСписок включает контроль доступа, ошибки конфигурации, цепочку поставок, криптографию, инъекции, небезопасный дизайн, аутентификацию, целостность, журналирование и обработку исключительных условий. [Первоисточник OWASP](https://top10.owasp.org/2025/) объясняет категории и ограничения перечня. Это отправная точка аудита, а не доказательство полноты проверки продукта.\n\n## Контроль доступа\n\nВход подтверждает пользователя, но объект ещё должен принадлежать ему. Для каждого обработчика запиши, кто его вызывает, какой объект получает и где проверяется право. Изменение номера заказа не должно открывать чужую запись. Админская кнопка скрыта на клиенте — сервер всё равно обязан проверять роль.\n\nПоля запроса принимай по разрешённому перечню. Пользователь не должен назначать себе роль или обходить лимит, добавив поле в JSON. Если данные доступны через Supabase, проверь RLS и политики для реальных ролей.\n\n## Конфигурация и криптография\n\nОтладочные страницы, подробные ошибки и опасные настройки по умолчанию проверяются в среде деплоя. Секреты хранятся на сервере в предназначенном механизме, а не в клиентском коде. Для паролей используются специальные алгоритмы с солью. CORS, заголовки и CSRF настраиваются под выбранный способ аутентификации.\n\n## Цепочка поставок\n\nДля зависимости выясни назначение, реальный источник и версию. Lockfile помогает повторить сборку. Скрипты установки и навыки агента тоже исполняемый либо управляющий материал: их нужно проверять. Выдуманное моделью имя пакета может быть зарегистрировано посторонним, поэтому команда установки требует сверки с настоящим проектом.\n\nНе удаляй зависимости автоматически только потому, что агент предложил заменить их коротким кодом. Сначала оцени использование, поддержку и цену самостоятельного сопровождения.\n\n## Входные данные\n\nПроверь формы, URL, загрузки, вебхуки и ответы внешних сервисов. SQL-запросы параметризуются. Вывод пользовательского текста экранируется под контекст. Подпись вебхука сверяется до изменения базы. Загрузка по пользовательскому URL не должна открывать внутренние адреса. Расширение файла не доказывает его формат.\n\n## Гонки, лимиты и дизайн\n\nПрогони два одновременных запроса к операциям начисления, списания и активации. Для защиты нужны согласованные проверки, уникальные ограничения, блокировки или ключи идемпотентности. Rate limit работает на сервере. Разбери также последовательность допустимых действий: бизнес-правило может обходиться без подозрительного запроса.\n\n## Аутентификация, целостность и ошибки\n\nПроверь срок и отзыв сессий, восстановление входа, проверки подписи и источника артефактов. После отказа внешнего сервиса состояние должно оставаться корректным. Ошибка проверки прав не должна разрешать действие по умолчанию. Пользователь получает понятный отказ, оператор — диагностическую запись без секретов.\n\n## Инструменты\n\n```sh\nnpm audit --omit=dev\n```\n\nСканер зависимостей ищет известные уязвимости, а сканер секретов — ключи, включая историю Git. Gitleaks, OSV Scanner и Nuclei упомянуты в исходной подборке; команды запуска сверяй с их официальными версиями. Проверяй только разрешённые адреса, учитывая влияние активного сканирования на сервис.\n\nНайденный в истории ключ сначала отзывается и заменяется. Удаление строки или коммита не делает прежний ключ безопасным.\n\n## Ручные сценарии\n\nВ тестовой среде открой продукт без входа, зайди вторым пользователем, запроси чужой объект и повтори одно событие. Проверь пустые данные, отказ сети и параллельное действие. Автоматический сканер может пропустить ошибки бизнес-логики.\n\n## Формат отчёта\n\nКаждая находка содержит файл и строку, необходимые условия, входные данные, последствие и способ проверки. По каждой категории укажи результат: подтверждена проблема, проверенные сценарии прошли либо категория не применима с причиной. Непроверенные области перечисляются отдельно.\n\nПеред публикацией закрой подтверждённые риски по приоритету и повтори сценарий, который показывал проблему. Зелёная сборка сама по себе не подтверждает безопасность.","cover_url":null,"minutes":4,"xp":60,"copy_text":null,"quiz":[],"published":true,"kind":"lesson","emoji":"🛡️","gradient":"ocean","video_url":null,"pinned":false,"position":52,"free_preview":false,"course_key":null},{"key":"feed-53","source_index":53,"source_title":"Чек-лист по 152-ФЗ","source_type":"guide","title":"Персональные данные: девять проверок перед запуском","category":"Закон","subtitle":"Формы, аккаунты, аналитика и журналы могут содержать персональные данные. Обязанности зависят от реальной обработки, правового основания и применимой юрисдикции. Этот материал структурирует проверку для специалиста, а не заменяет юридическое заключение.","body":"Формы, аккаунты, аналитика и журналы могут содержать персональные данные. Обязанности зависят от реальной обработки, правового основания и применимой юрисдикции. Этот материал структурирует проверку для специалиста, а не заменяет юридическое заключение.\n\n## 1. Уведомление регулятора\n\nОпредели, кто является оператором, какие цели и категории данных используются и применимы ли исключения. Если уведомление требуется, его подают до начала обработки. Проверка в реестре не заменяет сверку содержания поданного документа с текущей деятельностью.\n\n## 2. Публичная политика\n\nПолитика должна описывать реальный процесс и быть доступна там, где данные собираются. Рекомендации Роскомнадзора выделяют общие положения, цели, основания, категории данных и субъектов, условия обработки, обновление и уничтожение, ответы на обращения.\n\nУдобна таблица: цель — основание — данные — люди — срок — получатели. Документ другой компании можно использовать как пример структуры, но её цели, подрядчики и сроки не становятся твоими автоматически.\n\n## 3. Корректное основание и согласие\n\nНе для любой обработки единственное основание — согласие; сначала выясни применимое основание. Там, где используется согласие, человек должен понимать цель, состав данных, оператора, срок и отзыв. Начиная с 1 сентября 2025 года согласие оформляется отдельно от иных подтверждаемых документов. Предустановленная галочка не демонстрирует самостоятельного волеизъявления.\n\nПисьменное согласие имеет установленный состав сведений. Не собирай паспортные данные для каждой обычной формы только потому, что они перечислены в требованиях к специальной письменной форме: необходимость и форму определяют по конкретному процессу.\n\n## 4. Разные цели — разные проверки\n\nРабота сервиса, реклама и распространение данных имеют разные требования. Согласие на обслуживание не означает автоматически согласия на рекламные сообщения. Публичный профиль требует отдельной оценки требований к распространению. Фиксируй, какую версию и когда подтвердил человек, а также отзыв.\n\n## 5. Локализация\n\nПроверь требования к первичной обработке данных граждан России и реальное расположение используемых баз. Название зарубежного или российского поставщика не доказывает географию конкретного ресурса. Нужны договорные сведения и конфигурация размещения.\n\n## 6. Передача за границу\n\nСоставь перечень внешних баз, аналитики, почтовых и ИИ-сервисов. Определи, какие данные и кому передаются. Требования к уведомлению, оценке получателя и моменту начала передачи зависят от страны и условий. Не применяй единую задержку десять дней ко всем случаям без проверки нормы.\n\n## 7. Внутренние документы и защита\n\nДля организации проверь назначение ответственного, локальные акты, оценку вреда и угроз, права доступа, обучение и учёт обращений. Биометрия, специальные категории и данные детей требуют отдельного разбора. Технические меры должны соответствовать установленным угрозам.\n\n## 8. Инцидент\n\nПодготовь процесс выявления, фиксации и расследования. В исходной статье названы сроки первоначального уведомления 24 часа и сообщения результатов расследования 72 часа. До применения проверь текущую норму и то, какое событие запускает отсчёт. Взаимодействие с ГосСОПКА рассматривается отдельно по применимым требованиям.\n\nКонтакты, форма сообщения и ответственный должны быть известны до инцидента. Сохраняй факты и время обнаружения; не подменяй расследование догадкой о виновнике.\n\n## 9. Запросы, отзыв и уничтожение\n\nОрганизуй канал обращений и подтверждение полномочий заявителя. Исходник перечисляет ориентиры: ответ — десять рабочих дней с возможным продлением, исправление — семь рабочих дней, прекращение и уничтожение после отзыва — до тридцати дней при применимости соответствующего основания. Законные основания дальнейшего хранения и исключения нужно проверять отдельно.\n\nДля уничтожения нужны подтверждающие документы и, где требуется, выгрузка журнала. Если данные получены от другого лица, проверь обязанность информирования субъекта и исключения.\n\n## Где сверять\n\n[Портал Роскомнадзора](https://pd.rkn.gov.ru/) содержит формы, реестры и официальные материалы. Финальные сроки, исключения и санкции сверяются по действующей редакции закона. Суммы штрафов исходной статьи здесь не представлены как актуальный расчёт ответственности.","cover_url":null,"minutes":4,"xp":60,"copy_text":null,"quiz":[],"published":true,"kind":"lesson","emoji":"⚖️","gradient":"candy","video_url":null,"pinned":false,"position":53,"free_preview":false,"course_key":null},{"key":"feed-54","source_index":54,"source_title":"Штрафы за вайбкодинг","source_type":"guide","title":"Правовые риски цифрового продукта","category":"Закон","subtitle":"Ответственность зависит от действий продукта и его владельца. Использование агента для написания кода не освобождает от требований к данным, рекламе, платежам, налогам, лицензиям и потребителям. Точная квалификация и сумма зависят от обстоятельств и действующего закона.","body":"Ответственность зависит от действий продукта и его владельца. Использование агента для написания кода не освобождает от требований к данным, рекламе, платежам, налогам, лицензиям и потребителям. Точная квалификация и сумма зависят от обстоятельств и действующего закона.\n\n## Персональные данные\n\nПроверь основание обработки, публичные документы, уведомления, локализацию и меры защиты. Утечка и несвоевременное сообщение о ней могут образовывать разные нарушения. Количество людей, категории данных, повторность и статус оператора влияют на ответственность. Незаконно полученные данные могут затрагивать также уголовные нормы.\n\nПередача работы хостеру или подрядчику не означает автоматического переноса всех обязанностей. В договоре и процессе контроля нужны понятные права, меры и действия при инциденте. Не считай себя защищённым одной фразой о безопасности поставщика.\n\n## Реклама\n\nОпредели, что в публикации является рекламой, какие требования к идентификатору и передаче сведений применимы и кто участвует в цепочке. Проверь ограничения площадки и статус страницы. Рассылки требуют отдельной оценки согласия; подтверждения сохраняются до первой кампании.\n\nРекламодатель, изготовитель и распространитель могут иметь разные обязанности. Заказ у блогера не заменяет проверку того, что опубликовано.\n\n## Касса и чеки\n\nСпособ расчёта, статус продавца и применимый режим определяют требования к ККТ и чеку. Проверь оплату, возврат и передачу электронного чека предусмотренным способом. Утверждение «чек можно доставить только по email» слишком узкое: доступные варианты нужно сверять с законом и провайдером.\n\nТестовый заказ должен пройти путь от оплаты до доступа и необходимых документов. Сообщение платёжной системы не всегда является кассовым чеком.\n\n## Регистрация и налоги\n\nВыбери законную форму деятельности и проверь ограничения налогового режима. Оборот, вид услуги и работа с сотрудниками могут менять допустимость самозанятости. Тариф налога и пороги НДС из исходной статьи — исторические данные; расчёт на текущую дату требует отдельной проверки.\n\nНалоговые обязанности не исчезают потому, что продукт небольшой или платежи идут через иностранную площадку. Сохраняй учёт расчётов и документы.\n\n## Чужие материалы\n\nУ шрифтов, иконок, фотографий, библиотек и шаблонов отдельные лицензии. Для каждого проверь коммерческое использование, встраивание, распространение и требования к атрибуции. Агент может подключить файл из примера без оценки этих условий.\n\nСохрани лицензию и подтверждение покупки или разрешения. Возможная компенсация зависит от объекта, способа защиты права и редакции закона; одна универсальная сумма на весь проект ненадёжна.\n\n## Права покупателя\n\nНа сайте нужны сведения о продавце, содержании услуги, цене, порядке оплаты и возврата. Оферта не может сама отменить обязательные права потребителя. Для курса, цифрового файла и лицензии условия могут различаться; квалификацию проверяют по фактическому продукту.\n\nПредварительно выбранная платная дополнительная услуга и запрет возвратов требуют отдельной проверки. Обещания на лендинге должны совпадать с поставляемым результатом.\n\n## Авторизация, рекомендации и хостинг\n\nПроверь применимость требований к способам авторизации, информированию о рекомендательных технологиях, возрастной маркировке и поставщику хостинга. Исходная статья связывает их с изменениями законодательства 2025–2026 годов. По одному интерфейсному элементу нельзя определить все обязанности сервиса.\n\n## До запуска\n\nСобери таблицу: риск, применимость, действующая норма, подтверждающий документ, техническая мера и ответственный. Отдельно проверь данные, рекламу, чеки, налоги, права на ассеты, документы для покупателя и выбранные внешние сервисы.\n\nСудебные примеры о снижении штрафов не обещают такого же решения. План строят по обязанностям и цене нарушения, а не по надежде на предупреждение. Начни сверку с [официального опубликования правовых актов](https://publication.pravo.gov.ru/), [Роскомнадзора](https://rkn.gov.ru/), [ФАС](https://fas.gov.ru/) и [ФНС](https://www.nalog.gov.ru/).","cover_url":null,"minutes":3,"xp":60,"copy_text":null,"quiz":[],"published":true,"kind":"lesson","emoji":"⚖️","gradient":"lime","video_url":null,"pinned":false,"position":54,"free_preview":false,"course_key":null},{"key":"feed-55","source_index":55,"source_type":"tool","title":"Solar Icons: два веса для интерфейса","category":"Дизайн","subtitle":"В Solar Icons можно сочетать Linear для обычных элементов и Bold для акцентов.","cover_url":null,"minutes":2,"xp":20,"body":"В Solar Icons можно сочетать Linear для обычных элементов и Bold для акцентов. Разница в весе помогает обозначить выбранное состояние и выделить важное действие. Держи размеры и смысл одинаковыми в навигации, чтобы изменение рисунка не создавало впечатление новой функции.\n\n## Открыть ресурс\n\n- [solar-icons.vercel.app](https://solar-icons.vercel.app/)","copy_text":null,"quiz":[],"published":true,"kind":"lesson","emoji":"🎨","gradient":"aurora","video_url":null,"pinned":false,"position":55,"free_preview":false,"course_key":null},{"key":"feed-56","source_index":56,"source_type":"tool","title":"Как выбирать пару шрифтов для ролика","category":"Дизайн","subtitle":"Заголовок и подпись должны различаться по роли и сочетаться по характеру.","cover_url":"https://proninlearn.ru/posts/fonts-1-480w.webp","minutes":2,"xp":20,"body":"Заголовок и подпись должны различаться по роли и сочетаться по характеру. В исходном материале приведены четыре визуальных примера пар. Сравни их на своих словах: длинный заголовок, цифры и кириллица часто выглядят иначе, чем короткий образец. В ролике особенно важна читаемость на телефоне.\n\n## Открыть ресурс\n\n- [t.me](https://t.me/proninhere_bot)\n\n![Пример из подборки](https://proninlearn.ru/posts/fonts-2-480w.webp)\n\n![Пример из подборки](https://proninlearn.ru/posts/fonts-3-480w.webp)\n\n![Пример из подборки](https://proninlearn.ru/posts/fonts-4-480w.webp)","copy_text":null,"quiz":[],"published":true,"kind":"lesson","emoji":"🎨","gradient":"sunset","video_url":null,"pinned":false,"position":56,"free_preview":false,"course_key":null},{"key":"feed-57","source_index":57,"source_type":"tool","title":"Google Fonts: подобрать свободную гарнитуру","category":"Дизайн","subtitle":"Google Fonts помогает выбрать шрифт для сайта и скачать его файлы.","cover_url":"https://proninlearn.ru/posts/gfonts-604w.webp","minutes":2,"xp":20,"body":"Google Fonts помогает выбрать шрифт для сайта и скачать его файлы. Проверь кириллицу, нужные начертания и лицензию выбранной семьи. Если размещаешь шрифты у себя, передай агенту локальные файлы и попроси проверить, что страница корректно выглядит до завершения их загрузки.\n\n## Открыть ресурс\n\n- [fonts.google.com](https://fonts.google.com/)","copy_text":null,"quiz":[],"published":true,"kind":"lesson","emoji":"🎨","gradient":"mint","video_url":null,"pinned":false,"position":57,"free_preview":false,"course_key":null},{"key":"feed-58","source_index":58,"source_type":"tool","title":"Аниме-мотокросс: удержать персонажа в видео","category":"Видео","subtitle":"Короткий пример построен в два шага: сначала создаётся лист персонажа, затем он передаётся модели как строгий визуальный референс для ролика.","cover_url":"https://proninlearn.ru/posts/seedance-sheet-896w.webp","minutes":2,"xp":20,"body":"Короткий пример построен в два шага: сначала создаётся лист персонажа, затем он передаётся модели как строгий визуальный референс для ролика. Для своего сюжета закрепи лицо, одежду, цвета и пропорции на листе. После генерации проверь их в начале, середине и конце видео.\n\n## Открыть ресурс\n\n- [t.me](https://t.me/proninhere_bot)","copy_text":null,"quiz":[],"published":true,"kind":"lesson","emoji":"🎬","gradient":"ocean","video_url":null,"pinned":false,"position":58,"free_preview":false,"course_key":null},{"key":"feed-59","source_index":59,"source_type":"tool","title":"Mobbin: изучать реальные продуктовые экраны","category":"Дизайн","subtitle":"Mobbin собирает интерфейсы действующих продуктов.","cover_url":"https://proninlearn.ru/posts/mobbin-604w.webp","minutes":2,"xp":20,"body":"Mobbin собирает интерфейсы действующих продуктов. Такие примеры помогают разобрать формы, навигацию и сценарии, которыми люди уже пользуются. Смотри последовательность экранов целиком: отдельная красивая карточка мало говорит о том, как человек завершает задачу.\n\n## Открыть ресурс\n\n- [mobbin.com](https://mobbin.com/)","copy_text":null,"quiz":[],"published":true,"kind":"lesson","emoji":"🎨","gradient":"candy","video_url":null,"pinned":false,"position":59,"free_preview":false,"course_key":null},{"key":"feed-60","source_index":60,"source_type":"tool","title":"shadcn/ui: компоненты под свой проект","category":"Дизайн","subtitle":"shadcn/ui даёт основу для интерфейса, которую можно адаптировать в коде проекта.","cover_url":"https://proninlearn.ru/posts/shadcn-604w.webp","minutes":2,"xp":20,"body":"shadcn/ui даёт основу для интерфейса, которую можно адаптировать в коде проекта. Сначала выбери типографику, цвета и состояния, затем собирай экраны из согласованных элементов. Так готовые компоненты сохраняют удобство и получают внешний вид, подходящий конкретному продукту.\n\n## Открыть ресурс\n\n- [ui.shadcn.com](https://ui.shadcn.com/)","copy_text":null,"quiz":[],"published":true,"kind":"lesson","emoji":"🎨","gradient":"lime","video_url":null,"pinned":false,"position":60,"free_preview":false,"course_key":null},{"key":"feed-61","source_index":61,"source_type":"tool","title":"Sigma Studio: платная дизайн-система","category":"Дизайн","subtitle":"Sigma Studio — платная система интерфейсных компонентов.","cover_url":"https://proninlearn.ru/posts/sigma-604w.webp","minutes":2,"xp":20,"body":"Sigma Studio — платная система интерфейсных компонентов. В исходном приложении она используется как база с существенными изменениями под проект. Рассматривая её для себя, сравни состав, лицензию и нужные экраны: готовый набор всё равно требует настройки содержания и сценариев.\n\n## Открыть ресурс\n\n- [thesigma.co](https://thesigma.co/)","copy_text":null,"quiz":[],"published":true,"kind":"lesson","emoji":"🎨","gradient":"aurora","video_url":null,"pinned":false,"position":61,"free_preview":false,"course_key":null},{"key":"feed-62","source_index":62,"source_type":"tool","title":"Refero: разбирать решения крупных продуктов","category":"Дизайн","subtitle":"Refero пригодится для изучения визуальных систем и интерфейсных решений известных сервисов.","cover_url":"https://proninlearn.ru/posts/refero-604w.webp","minutes":2,"xp":20,"body":"Refero пригодится для изучения визуальных систем и интерфейсных решений известных сервисов. Выбери несколько экранов одного продукта и найди общие правила: расстояния, иерархию текста, вид кнопок и состояний. Эти наблюдения помогут сформулировать свою систему.\n\n## Открыть ресурс\n\n- [refero.design](https://refero.design/)","copy_text":null,"quiz":[],"published":true,"kind":"lesson","emoji":"🎨","gradient":"sunset","video_url":null,"pinned":false,"position":62,"free_preview":false,"course_key":null},{"key":"feed-63","source_index":63,"source_type":"tool","title":"Dprofile: работы русскоязычных дизайнеров","category":"Дизайн","subtitle":"В Dprofile можно посмотреть портфолио и проекты русскоязычных дизайнеров.","cover_url":"https://proninlearn.ru/posts/dprofile-604w.webp","minutes":2,"xp":20,"body":"В Dprofile можно посмотреть портфолио и проекты русскоязычных дизайнеров. Ищи примеры по нужной отрасли и типу носителя, затем отмечай конкретные решения для своей задачи. Ссылка на работу вместе с объяснением полезного приёма даёт агенту больше контекста, чем общая просьба сделать красиво.\n\n## Открыть ресурс\n\n- [dprofile.ru](https://dprofile.ru/)","copy_text":null,"quiz":[],"published":true,"kind":"lesson","emoji":"🎨","gradient":"mint","video_url":null,"pinned":false,"position":63,"free_preview":false,"course_key":null},{"key":"feed-64","source_index":64,"source_type":"tool","title":"MeiGen: промпты для изображений и видео","category":"Промпты","subtitle":"MeiGen собирает запросы для генерации картинок и роликов из визуальных примеров.","cover_url":"https://proninlearn.ru/posts/meigen-604w.webp","minutes":2,"xp":20,"body":"MeiGen собирает запросы для генерации картинок и роликов из визуальных примеров. Найди подходящий стиль, замени объект и условия съёмки, затем сравни несколько результатов. Сохрани удачный запрос вместе с моделью и настройками, чтобы повторить направление в следующем выпуске.\n\n## Открыть ресурс\n\n- [meigen.ai](https://meigen.ai/)","copy_text":null,"quiz":[],"published":true,"kind":"lesson","emoji":"💬","gradient":"ocean","video_url":null,"pinned":false,"position":64,"free_preview":false,"course_key":null},{"key":"course-1","source_type":"original_course_lesson","title":"Подключаем инструменты через MCP","subtitle":"Проверяем возможности агента до начала сборки","category":"Видео","body":"> Модуль 1 · Инструменты и рабочий процесс\n\nMCP помогает агенту обращаться к подключённому инструменту через понятный интерфейс. Для ролика это может быть работа с озвучкой, изображениями или монтажом. Само подключение не гарантирует, что агент умеет рендерить MP4: сначала нужно проверить доступные действия.\n\n## Минимальная связка\n\nВыбери агента, который открывает рабочую папку, читает и меняет файлы. Для голосовой дорожки можно подключить выбранный сервис озвучки, например ElevenLabs; изображения могут быть готовыми. Remotion создаёт видео из React-сцен. Подписка на чат и расходы внешнего API могут учитываться отдельно.\n\n## Проверка подключения\n\nУстанови интеграцию из официального источника в соответствии с инструкцией выбранного клиента. Ключ храни в предназначенном локальном механизме, вне Git и публичного кода. В новой сессии попроси агента перечислить доступные инструменты и их задачи, затем выполнить маленькое действие: открыть папку или создать тестовый кадр. Платный запрос запускается только когда понятны его параметры и расход.\n\nАгент должен различать доступный инструмент, предложение подключить его и результат уже выполненного действия. Если генератора изображений нет, используй готовый файл; не оставляй в сцене путь к воображаемому результату.\n\n## Задание\n\nСоздай список: инструмент, задача, способ подключения, расположение результата, ограничения и стоимость. Не вписывай в него сами ключи.\n\n## Результат\n\nРабочая папка открывается, хотя бы одна операция проверена, а агент знает, какие материалы получает от тебя. Подключение частного MCP из чужого курса для этих уроков не требуется.","position":1,"free_preview":false,"course_key":"ai-video","cover_url":null,"minutes":3,"xp":70,"copy_text":null,"quiz":[{"q":"Что подтверждает, что инструмент подключён?","options":["Агент выполнил разрешённую тестовую операцию","В сообщении написано название сервиса","В папке есть картинка-заглушка"],"correct":0,"explain":"Агент выполнил разрешённую тестовую операцию"}],"published":true,"kind":"lesson","emoji":"🎬","gradient":"candy","video_url":null,"pinned":false},{"key":"course-2","source_type":"original_course_lesson","title":"Готовим текст и референсы","subtitle":"Делаем входные материалы однозначными","category":"Видео","body":"> Модуль 1 · Инструменты и рабочий процесс\n\nХорошая сборка начинается с согласованного текста и нескольких понятных визуальных примеров. Агенту нужно знать смысл ролика, аудиторию и то, какую функцию выполняет каждый референс.\n\n## Учебная тема\n\nВозьмём выбор телефона под разные задачи. Главная мысль: сначала определить сценарий использования, затем сравнивать характеристики. Не обещай универсально лучший аппарат и не придумывай текущие цены. Для первого теста достаточно общего примера без торговых марок.\n\nНапиши короткий текст: вопрос зрителя, два–три критерия, сравнение сценариев и понятный вывод. Прочитай вслух и убери фразы, которые повторяют предыдущую мысль.\n\n## Карточка референса\n\nДля каждого примера укажи ссылку или локальный файл и полезный приём: размер заголовка, расположение объекта, переход, ритм, цвет. Отдельно объясни, что переносить нельзя. Это предотвращает копирование чужой композиции целиком там, где нужен только один приём.\n\nПроверь права на изображения, голос и музыку. Собственные файлы сложи в assets с понятными именами. У материалов должна быть реальная папка, а у ссылок — понятный источник.\n\n## Запрос агенту\n\nПередай цель, аудиторию, формат, приблизительную длительность, текст, материалы и ограничения. Попроси сначала найти противоречия и недостающие данные. Правки смысла согласуются до озвучки.\n\n## Задание\n\nПодготовь script.md и references.md. В первом — финальный текст, во втором — три примера с пояснениями. Составь перечень готовых и недостающих файлов.\n\n## Результат\n\nАгент может пересказать главную мысль без догадок; неизвестные факты обозначены, а каждая нужная картинка существует либо имеет согласованный способ подготовки.","position":2,"free_preview":false,"course_key":"ai-video","cover_url":null,"minutes":3,"xp":70,"copy_text":null,"quiz":[{"q":"Что полезнее передать вместе с референсом?","options":["Объяснение нужного приёма и его роли","Просьбу скопировать всё целиком","Только оценку «красиво»"],"correct":0,"explain":"Объяснение нужного приёма и его роли"}],"published":true,"kind":"lesson","emoji":"🎬","gradient":"lime","video_url":null,"pinned":false},{"key":"course-3","source_type":"original_course_lesson","title":"Собираем и правим сториборд","subtitle":"Проверяем последовательность до дорогой генерации","category":"Видео","body":"> Модуль 1 · Инструменты и рабочий процесс\n\nСториборд связывает речь с тем, что зритель видит на экране. На этом этапе проверяют мысль и порядок сцен, пока ещё легко переставить кадр или заменить пример.\n\n## Таблица сцен\n\nДля каждой сцены запиши номер, временной диапазон, фразу, визуальный объект, экранный текст, движение и переход. Если голоса ещё нет, тайминг приблизительный. После озвучки его уточняют по реальному аудио.\n\nУ учебного ролика могут быть четыре части: вопрос «как выбрать», сценарии использования, сравнение нужных характеристик и короткий вывод. Один экран раскрывает одну основную мысль. Полный текст озвучки не обязательно повторять на экране.\n\n## Три проверки\n\nСначала прочитай только речь: есть ли логическая связь? Затем посмотри только кадры: понятно ли, на что обращают внимание? Наконец проверь соответствие: нужный объект появляется к нужной фразе.\n\nВместо набора дорогих картинок используй блоки и подписи. Они показывают размеры и порядок. Красивый референс может скрыть слабую сцену; простая схема выявляет её раньше.\n\n## Правки\n\nФормулируй замечание конкретно: сцена 3 начинается раньше нужного слова; сравнение содержит слишком много пунктов; вывод не отвечает на вопрос первой сцены. Попроси обновить таблицу и объяснить изменения, затем утверди её как текущую версию.\n\n## Задание\n\nСоставь storyboard.md из четырёх–шести сцен. Вычитай его без эффектов и отметь один элемент, который можно убрать без потери смысла.\n\n## Результат\n\nПорядок сцен согласован, для каждого кадра есть функция и список материалов. Генерация и монтаж начинаются по этому плану, а изменения фиксируются в нём.","position":3,"free_preview":false,"course_key":"ai-video","cover_url":null,"minutes":3,"xp":70,"copy_text":null,"quiz":[{"q":"Что проверяют до генерации сложного визуала?","options":["Смысл и порядок сцен","Количество декоративных переходов","Финальный размер MP4"],"correct":0,"explain":"Смысл и порядок сцен"}],"published":true,"kind":"lesson","emoji":"🎬","gradient":"aurora","video_url":null,"pinned":false},{"key":"course-4","source_type":"original_course_lesson","title":"Доводим ролик до финала","subtitle":"Делаем замечания по конкретному времени и кадру","category":"Видео","body":"> Модуль 1 · Инструменты и рабочий процесс\n\nПредварительный ролик нужен для просмотра целого. Сначала оцени содержание и синхронизацию, затем детали оформления. Правка цвета не решит проблему, если вывод не следует из сравнения.\n\n## Порядок просмотра\n\nПосмотри ролик со звуком без остановок. Запиши, где теряется мысль, не хватает времени на чтение или кадр не совпадает с речью. Второй раз проверь его без звука на телефоне: остаются ли понятными главный вопрос и вывод?\n\nПосле этого проверь начало и конец каждой сцены. Текст не обрезан, картинки не растянуты, переход не закрывает смысловую фразу. Включи тихую громкость и убедись, что речь остаётся различимой.\n\n## Формат замечания\n\nУкажи время, сцену, наблюдаемую проблему и желаемый результат. Например: «00:12, сцена 3: название критерия видно меньше секунды; оставь его до окончания соответствующей фразы». Не называй реализацию без необходимости: агент может исправить тайминг проще другим способом.\n\nГруппируй связанные замечания в один проход. После правок просматривай затронутые сцены и полный ролик, если изменились длительность или звук.\n\n## Финальная версия\n\nСохрани итоговый сториборд, актуальные исходники и файл с уникальным именем версии. Экспорт считается завершённым после открытия MP4 и проверки его длительности, изображения и звука.\n\n## Задание\n\nСоставь три замечания к тестовому ролику в формате «время — проблема — результат» и проверь их после исправления.\n\n## Результат\n\nВсе существенные замечания закрыты проверкой. В папке output лежит однозначно обозначенный финальный файл, а рядом сохранены исходники, из которых он собран.","position":4,"free_preview":false,"course_key":"ai-video","cover_url":null,"minutes":3,"xp":70,"copy_text":null,"quiz":[{"q":"Как сформулировать полезное замечание?","options":["Назвать время, проблему и нужный результат","Написать «плохо выглядит»","Попросить больше эффектов во всех сценах"],"correct":0,"explain":"Назвать время, проблему и нужный результат"}],"published":true,"kind":"lesson","emoji":"🎬","gradient":"sunset","video_url":null,"pinned":false},{"key":"course-5","source_type":"original_course_lesson","title":"Настраиваем свой визуальный стиль","subtitle":"Превращаем удачные решения в повторяемые правила","category":"Видео","body":"> Модуль 1 · Инструменты и рабочий процесс\n\nСтиль становится устойчивым, когда его можно повторить на новом тексте. Для этого агенту нужны конкретные размеры, роли и примеры, а не одна просьба сделать как в предыдущем выпуске.\n\n## Минимальный набор правил\n\nОпредели формат кадра, поля, палитру, шрифты и иерархию. У заголовка, пояснения и акцента разные роли. Задай допустимые размеры текста и ограничения длины. Назови несколько используемых компонентов: карточка факта, сравнение, подпись, финальный экран.\n\nДля движения опиши появление, удержание и уход. Укажи, какие элементы сохраняют положение между сценами. Постоянная сетка уменьшает случайное изменение размеров после правки текста.\n\n## Эталон\n\nСобери одну сцену с заголовком, длинной подписью, числом и изображением. Проверь её на телефоне. Это образец для других сцен, где видно не только красиво выбранное слово, но и сложное содержание.\n\nСохрани правила в style.md, а значения — в токенах проекта. Агент использует эти значения при создании экранов. Дублирование цветов и расстояний в каждом компоненте делает дальнейшую настройку труднее.\n\n## Развитие системы\n\nПосле нового выпуска добавляй правило, если проблема повторяется. Один исключительный кадр не обязательно требует глобального компонента. У системы должен оставаться небольшой понятный набор решений.\n\n## Задание\n\nОпиши одну палитру, две текстовые роли, поля и три компонента. Собери второй экран по тем же правилам без копирования готовой картинки.\n\n## Результат\n\nНовый текст выглядит частью того же проекта, длинные слова помещаются, а изменение одного токена обновляет нужные сцены предсказуемо.","position":5,"free_preview":false,"course_key":"ai-video","cover_url":null,"minutes":3,"xp":70,"copy_text":null,"quiz":[{"q":"Что позволяет повторить стиль на новом тексте?","options":["Правила, токены и проверенный эталон","Только снимок одного красивого кадра","Новый набор цветов для каждой сцены"],"correct":0,"explain":"Правила, токены и проверенный эталон"}],"published":true,"kind":"lesson","emoji":"🎬","gradient":"mint","video_url":null,"pinned":false},{"key":"course-6","source_type":"original_course_lesson","title":"Продолжаем проект в новом чате","subtitle":"Передаём состояние работы через файлы","category":"Видео","body":"> Модуль 1 · Инструменты и рабочий процесс\n\nНовая сессия должна быстро понять, что уже готово и какая правка требуется. Надёжная передача состояния лежит в проекте вместе с исходниками. Длинная история чата не заменяет этот набор.\n\n## Что сохранить\n\nВ README запиши запуск, предпросмотр и экспорт. В storyboard.md — текущие сцены. В style.md — визуальные правила. В status.md — согласованную версию, незавершённые задачи и результаты последней проверки. Секреты и токены сюда не входят.\n\nФайлы материалов имеют стабильные имена. Если картинка заменена, это отражено в соответствующей сцене. Итоговый MP4 сохраняется отдельно от предыдущих вариантов.\n\n## Начало новой сессии\n\nОткрой ту же папку и попроси агента прочитать правила, статус и нужный участок. Пусть коротко подтвердит состояние: что работает, какая версия финальная, что нужно изменить. Это выявляет ошибочное понимание до правки.\n\nПеред изменением проверь Git status и исходный предпросмотр. Незавершённые правки другого человека не должны исчезать при «очистке». Задача новой сессии ограничена тем, что ты сформулировал.\n\n## Завершение\n\nАгент обновляет состояние после проверки результата. Полезный вывод о повторяющейся проблеме переносится в правило; временная догадка не становится постоянной инструкцией.\n\n## Задание\n\nЗакрой текущую сессию, открой новую и попроси изменить одну подпись. Перед этим агент должен определить текущий ролик и команду просмотра из файлов.\n\n## Результат\n\nПравка сделана без повторного объяснения всего проекта, текущая версия сохранена, а статус совпадает с реальными файлами и проверками.","position":6,"free_preview":false,"course_key":"ai-video","cover_url":null,"minutes":3,"xp":70,"copy_text":null,"quiz":[{"q":"Где хранить устойчивые договорённости проекта?","options":["В правилах и документах рядом с исходниками","Только в прошлом чате","В имени случайного временного файла"],"correct":0,"explain":"В правилах и документах рядом с исходниками"}],"published":true,"kind":"lesson","emoji":"🎬","gradient":"ocean","video_url":null,"pinned":false},{"key":"course-7","source_type":"adapted_intro","title":"Как агент собирает ролик","subtitle":"От текста и голоса до готового видео","category":"Видео","body":"> Модуль 2 · Подготовка проекта\n\nРолик получается из содержания, материалов, времени и экранов. Агент пишет код сцен, подключает изображения и звук, расставляет события по времени и рендерит итоговый MP4. Человек проверяет факты, выбирает подачу и оценивает результат.\n\n## Путь выпуска\n\n1. Ты передаёшь текст и готовые материалы.\n2. Подготавливается голосовая дорожка; ты слушаешь и выбираешь вариант.\n3. Определяются таймкоды фраз или слов.\n4. Агент предлагает план экранов, ты проверяешь смысл и порядок.\n5. Собираются сцены, анимация и субтитры.\n6. После просмотра и правок рендерится MP4.\n\nЕсли голос или изображения уже готовы, повторная генерация не нужна. Агент может помочь с черновиком текста, но его факты и обещания проверяет автор.\n\n## Две рабочие связки\n\nClaude Code работает с проектом и может обращаться к подключённым сервисам. Озвучку можно готовить в ElevenLabs, а изображения и распознавание — через доступный API. Codex также работает с файлами; дополнительные инструменты зависят от среды и подключения. Отсутствующую возможность нужно выяснить до сборки.\n\nAPI позволяет программе вызвать сервис. Для него нужны отдельные настройки и иногда оплата, даже если уже есть подписка на обычный чат. Ключи сохраняются локально или на сервере в предназначенном механизме, вне публичного кода.\n\n## Рендер\n\nRemotion превращает React-сцены в видео. [Лицензия](https://www.remotion.pro/license) разрешает бесплатное использование в предусмотренных условиях, в том числе для отдельных людей и небольших команд; крупной коммерческой организации может требоваться корпоративная лицензия.\n\n## Учебный выпуск\n\nБудем собирать короткий ролик о выборе телефона по задачам. Сначала сделаем простой файл, затем добавим визуал и голос. Каждый этап должен иметь проверяемый результат.\n\n## Задание и результат\n\nОпиши один выпуск: аудитория, мысль, готовые материалы и выбранный агент. Убедись, что агент открывает папку проекта. Начинай с короткого примера, чтобы понять реальные расходы до покупки лишних сервисов.","position":7,"free_preview":true,"course_key":"ai-video","cover_url":null,"minutes":3,"xp":70,"copy_text":null,"quiz":[{"q":"Кто проверяет факты и итоговую подачу?","options":["Автор ролика","Только генератор изображений","Никто, если рендер завершился"],"correct":0,"explain":"Автор ролика"}],"published":true,"kind":"lesson","emoji":"🎬","gradient":"candy","video_url":null,"pinned":false},{"key":"course-8","source_type":"original_course_lesson","title":"Проект и память агента","subtitle":"Организуем файлы для одного выпуска","category":"Видео","body":"> Модуль 2 · Подготовка проекта\n\nСтабильный проект отделяет код, материалы и результаты. Агенту легче работать, когда место каждого файла понятно и правила не противоречат друг другу.\n\n## Рабочие папки\n\n```text\nvideo-project/\n  src/          сцены и компоненты\n  public/       доступные рендеру материалы\n  docs/         текст, план и стиль\n  output/       готовые видео\n  README.md     запуск и проверка\n```\n\nЭто пример организации; шаблон Remotion может иметь свой состав. Не переименовывай технические папки вслепую. Для файла озвучки используй понятное имя, например voice-v1.wav, а связь со сценами опиши в плане.\n\n## Инструкции агенту\n\nВ CLAUDE.md или AGENTS.md запиши команды проекта, место материалов и способ проверки. Общие привычки относятся к личным настройкам, а палитра и композиция этого ролика — к проекту. Один основной файл содержит важное; подробности лежат в тематических документах.\n\nПамять помогает избежать повторного объяснения, но проверка всё равно нужна. Попроси агента назвать файлы, которые он прочитал перед задачей, и не считай наличие документа доказательством его применения.\n\n## Версии\n\nТекст, план и исходники должны описывать одну актуальную сборку. Не смешивай голос из первой версии с таймкодами второй. У значимой правки есть краткая запись причины.\n\n## Задание\n\nСоздай структуру проекта и README с командами просмотра и экспорта после выбора шаблона. Добавь документ с текущим текстом и перечнем материалов.\n\n## Результат\n\nАгент может найти каждый нужный файл по README, понимает актуальную версию и выполняет одну небольшую правку без поиска по случайным папкам.","position":8,"free_preview":false,"course_key":"ai-video","cover_url":null,"minutes":3,"xp":70,"copy_text":null,"quiz":[{"q":"Почему нельзя смешать новую озвучку со старыми таймкодами?","options":["Реальное время слов могло измениться","Изменится название папки","Это всегда уменьшает размер видео"],"correct":0,"explain":"Реальное время слов могло измениться"}],"published":true,"kind":"lesson","emoji":"🎬","gradient":"lime","video_url":null,"pinned":false},{"key":"course-9","source_type":"original_course_lesson","title":"Права агента и сохранность проекта","subtitle":"Создаём проверяемую точку возврата","category":"Видео","body":"> Модуль 2 · Подготовка проекта\n\nАгент меняет файлы на компьютере. До большого цикла правок сохрани рабочий результат и отдели учебный проект от боевых систем. Это позволяет восстановить предыдущую версию без пересборки по памяти.\n\n## Git\n\nПосмотри git status и git diff. Проверь, какие файлы действительно относятся к задаче. Настрой исключение зависимостей, временных результатов и секретов, затем сохрани проверенное состояние коммитом. Источники ролика и документы должны попадать в учёт по выбранной политике, тяжёлые медиа могут храниться отдельно с резервной копией.\n\n## Доступ\n\nДай агенту рабочую папку и необходимые инструменты. Для учебного ролика не нужны права на продакшен-базу или чужие аккаунты. Настрой подтверждение дорогостоящих и разрушительных операций по возможностям клиента.\n\nПароли и ключи не передавай в текст сцены или публичную конфигурацию. Если ключ оказался в репозитории, сначала отзови его, затем устраняй причину попадания.\n\n## Проверка возврата\n\nНа небольшом безопасном примере сделай правку текста, посмотри diff и верни только эту правку предназначенным способом. Сначала сохрани нужную незавершённую работу. Git не заменяет резервирование файлов, которые не входят в репозиторий.\n\n## Задание\n\nСохрани исходную версию, измени одну подпись и восстанови её после просмотра diff. Запиши, какие папки включены в резервную копию.\n\n## Результат\n\nЕсть подтверждённая точка возврата, секреты исключены, а права агента соответствуют проекту. Ты знаешь, как восстановить код и нужные материалы.","position":9,"free_preview":false,"course_key":"ai-video","cover_url":null,"minutes":3,"xp":70,"copy_text":null,"quiz":[{"q":"Что сделать до большой серии правок?","options":["Сохранить проверенное рабочее состояние","Удалить все предыдущие файлы","Дать агенту доступ ко всем проектам"],"correct":0,"explain":"Сохранить проверенное рабочее состояние"}],"published":true,"kind":"lesson","emoji":"🎬","gradient":"aurora","video_url":null,"pinned":false},{"key":"course-10","source_type":"original_course_lesson","title":"Первый рендер","subtitle":"Проверяем цепочку на одной простой сцене","category":"Видео","body":"> Модуль 2 · Подготовка проекта\n\nПервый рендер проверяет инструменты и формат. Здесь достаточно заголовка, фона и короткой анимации. Голос и сложные картинки добавляются после того, как простой файл открывается.\n\n## Параметры теста\n\nВыбери вертикальный кадр 1080×1920, частоту 30 кадров в секунду и длительность пять секунд. Это 150 кадров. В Remotion композиция хранит размеры, fps и durationInFrames, а компонент описывает изображение на каждом кадре.\n\nПопроси агента создать минимальный проект по [официальному руководству](https://www.remotion.dev/docs/) и показать команду предпросмотра. Установку и лицензирование выполняют по актуальным условиям.\n\n## Простой эффект\n\nЗаголовок может появляться за первые пятнадцать кадров и оставаться до конца. Для вычисления состояния используются useCurrentFrame и interpolate. Укажи граничное поведение: значение после конца появления не продолжает расти.\n\n```tsx\nconst frame = useCurrentFrame();\nconst opacity = interpolate(frame, [0, 15], [0, 1], {\n  extrapolateLeft: 'clamp',\n  extrapolateRight: 'clamp',\n});\n```\n\nЭтот фрагмент относится к React-компоненту Remotion и требует импортов соответствующих функций; это не самостоятельный проект.\n\n## Экспорт\n\nОткрой предпросмотр, затем отрендери выбранную композицию в MP4. Запись файла не завершает проверку: открой его в плеере, проверь длительность, размер кадра и первые и последние секунды.\n\n## Задание\n\nСоздай тестовую сцену с собственной подписью и сохрани файл output/test-v1.mp4. Покажи агенту найденное отличие между просмотром и результатом, если оно есть.\n\n## Результат\n\nПять секунд видео воспроизводятся, текст помещается, частота и размеры известны. README содержит реально работающие команды проекта.","position":10,"free_preview":false,"course_key":"ai-video","cover_url":null,"minutes":3,"xp":70,"copy_text":null,"quiz":[{"q":"Сколько кадров в пяти секундах при 30 fps?","options":["150","30","500"],"correct":0,"explain":"150"}],"published":true,"kind":"lesson","emoji":"🎬","gradient":"sunset","video_url":null,"pinned":false},{"key":"course-11","source_type":"original_course_lesson","title":"Стиль и композиция кадра","subtitle":"Строим читаемую сетку для телефона","category":"Видео","body":"> Модуль 3 · Визуал\n\nВертикальный ролик часто смотрят на небольшом экране. Композиция должна выделять главное и оставлять место интерфейсу платформы. Декор не должен закрывать подпись или конкурировать с выводом.\n\n## Сетка\n\nРаздели кадр на поля и рабочую область. Начни с фиксированных внешних отступов и двух–трёх уровней текста. Для учебного проекта попробуй одинаковые поля слева и справа, заголовок в верхней части, объект в центре и короткую подпись ниже. Это исходная схема, которую нужно проверить на реальном телефоне.\n\nМесто кнопок и подписи платформы зависит от площадки. Проверь актуальный интерфейс публикации или безопасные зоны в её требованиях. Универсальный отступ не гарантирует видимость во всех приложениях.\n\n## Иерархия\n\nОдна мысль получает главный акцент. Заголовок формулирует вопрос, число или объект его объясняет, подпись добавляет деталь. Если всё одинаково крупное и яркое, зрителю приходится самому выбирать порядок чтения.\n\n## Проверка текста\n\nИспользуй длинный заголовок, несколько цифр и кириллицу. Они выявляют переполнение лучше короткого образца. Проверь контраст, интервалы между строками и длительность удержания. Уменьшение всего текста — не первый ответ на переполненный экран; часто полезнее сократить или разделить содержание.\n\n## Задание\n\nСобери два статичных кадра: вопрос и сравнение. Посмотри их в масштабе телефонного экрана и попроси другого человека назвать главное за несколько секунд.\n\n## Результат\n\nПонятен порядок чтения, подписи видны, а элементы управления площадки не закрывают важные части. Сетка записана в правилах проекта.","position":11,"free_preview":false,"course_key":"ai-video","cover_url":null,"minutes":3,"xp":70,"copy_text":null,"quiz":[{"q":"Что помогает зрителю понять порядок чтения?","options":["Выраженная иерархия элементов","Одинаковая яркость всех деталей","Как можно больше текста в кадре"],"correct":0,"explain":"Выраженная иерархия элементов"}],"published":true,"kind":"lesson","emoji":"🎬","gradient":"mint","video_url":null,"pinned":false},{"key":"course-12","source_type":"original_course_lesson","title":"Плашки и библиотека компонентов","subtitle":"Собираем повторяемые сцены","category":"Видео","body":"> Модуль 3 · Визуал\n\nКарточка факта, сравнительная колонка и подпись повторяются между роликами. Выделение таких элементов в компоненты помогает сохранить размеры и движение при изменении содержания.\n\n## Три базовых элемента\n\nНачни с карточки критерия, блока сравнения и итоговой плашки. У каждого определи входы: заголовок, текст, значение, иконка и акцент. Цвета, радиусы и расстояния приходят из токенов проекта.\n\nПример интерфейса карточки: title — короткое имя, value — число или ответ, note — пояснение, accent — разрешённый вариант палитры. Запрети компоненту самостоятельно выбирать случайную гарнитуру для длинного текста.\n\n## Состояния\n\nПроверь короткое и длинное содержание, отсутствие необязательной подписи и разные числа. В видео нужны также начало появления, удержание и уход. Снимок одного удачного состояния не подтверждает весь компонент.\n\n## Движение\n\nСогласуй правила появления нескольких карточек: вместе либо с небольшой задержкой. Тайминг должен объяснять речь. Изменение порядка анимации фиксируется в сцене, а базовая механика остаётся внутри компонента.\n\nЕсли новый экран требует совершенно другого поведения, сначала выясни, повторится ли это дальше. Не превращай одну особую сцену в чрезмерно сложную универсальную библиотеку.\n\n## Задание\n\nСделай одну карточку и используй её для двух критериев телефона. Поменяй размер отступа через общий токен и проверь обе сцены.\n\n## Результат\n\nОбе карточки обновляются согласованно, длинные подписи помещаются, а правка содержания не требует повторной настройки всей вёрстки.","position":12,"free_preview":false,"course_key":"ai-video","cover_url":null,"minutes":3,"xp":70,"copy_text":null,"quiz":[{"q":"Откуда компоненту брать общие расстояния?","options":["Из токенов системы","Из случайного значения в каждом кадре","Из размера первого изображения"],"correct":0,"explain":"Из токенов системы"}],"published":true,"kind":"lesson","emoji":"🎬","gradient":"ocean","video_url":null,"pinned":false},{"key":"course-13","source_type":"original_course_lesson","title":"Картинки и постоянный персонаж","subtitle":"Готовим материалы с единым визуальным направлением","category":"Видео","body":"> Модуль 3 · Визуал\n\nРазные генерации могут менять пропорции, лицо, освещение и палитру. Для серии роликов нужна явная визуальная опора: лист персонажа или описание предмета плюс одинаковые ограничения.\n\n## Лист персонажа\n\nПодготовь фронтальный вид, профиль и несколько нужных эмоций. Закрепи признаки: форма лица, волосы, одежда, цвета и характер линий. Используй только персонажей и изображения, на которые у тебя есть необходимые права.\n\nДля учебного ролика персонаж необязателен. Изображения телефона или условные схемы часто объясняют сравнение проще. Не добавляй героя, если он не помогает содержанию.\n\n## Запрос к генератору\n\nНазови объект, действие, вид кадра, стиль, свет, фон и требования к свободному месту для подписи. Передай референс поддерживаемым инструментом. Текст «всегда один персонаж» сам по себе не гарантирует согласованность нескольких запусков.\n\n## Приёмка\n\nСравни изображения рядом. Проверь лицо или предмет, количество деталей, направление света и размеры. Затем посмотри файл в настоящей сцене: красивое полное изображение может плохо работать после обрезки.\n\nСохраняй принятые файлы локально с понятным именем. Номер генерации и настройки помогают повторить направление. Изменение только пути без скачанного файла оставляет сцену неисправной.\n\n## Задание\n\nПодготовь два изображения одного объекта для разных сцен. Выпиши три признака, которые совпадают, и один допустимый вариант отличия.\n\n## Результат\n\nМатериалы сочетаются, существуют на диске и проверены в кадре. Права и источник записаны в списке ассетов.","position":13,"free_preview":false,"course_key":"ai-video","cover_url":null,"minutes":3,"xp":70,"copy_text":null,"quiz":[{"q":"Как проверять единство персонажа?","options":["Сравнивать принятые изображения рядом и в сценах","Читать только текст запроса","Считать совпадение названий файлов"],"correct":0,"explain":"Сравнивать принятые изображения рядом и в сценах"}],"published":true,"kind":"lesson","emoji":"🎬","gradient":"candy","video_url":null,"pinned":false},{"key":"course-14","source_type":"original_course_lesson","title":"Поиск вдохновения","subtitle":"Превращаем референс в понятное задание","category":"Видео","body":"> Модуль 3 · Визуал\n\nРеференс полезен, когда объясняет конкретный приём. Просмотр десятков красивых работ без отбора редко превращается в ясную сцену. Ищи пример под задачу: сравнение, акцент на числе, переход или движение объекта.\n\n## Источники\n\nДля композиции подойдут Genery и Geometric Shots, для интерфейсов — Mobbin и Refero, для моушна — библиотеки визуальных подборок. У продукта изучай последовательность экранов, у ролика — время появления элементов и связь со звуком.\n\n## Разбор\n\nЗапиши, где находится главный объект, как выделен текст, сколько действий происходит одновременно и чем завершается сцена. Объясни, почему приём подходит твоему содержанию. Если референс держится на длинной паузе, а твоя речь быстрая, перенос без адаптации не сработает.\n\nОдин пример может задавать типографику, другой — переход. Не соединяй одновременно все разные стили. Выбери основное направление и небольшое число приёмов.\n\n## Права\n\nСсылка на работу служит для обсуждения. Возможность скачивания не означает права вставить её в свой ролик. Для итоговой сборки используй разрешённые материалы и собственные решения.\n\n## Задание\n\nНайди три референса. Для каждого составь строку: источник — полезный приём — сцена своего ролика — что адаптируем. Затем исключи один пример, который не поддерживает главную мысль.\n\n## Результат\n\nАгент получает небольшую подборку с ясным назначением каждого примера и может собрать черновой экран без копирования всей чужой работы.","position":14,"free_preview":false,"course_key":"ai-video","cover_url":null,"minutes":3,"xp":70,"copy_text":null,"quiz":[{"q":"Когда референс превращается в полезное задание?","options":["Когда названы приём и его роль в своей сцене","Когда сохранено сто случайных картинок","Когда просишь повторить весь чужой ролик"],"correct":0,"explain":"Когда названы приём и его роль в своей сцене"}],"published":true,"kind":"lesson","emoji":"🎬","gradient":"lime","video_url":null,"pinned":false},{"key":"course-15","source_type":"original_course_lesson","title":"Текст и озвучка","subtitle":"Подготавливаем речь до монтажа","category":"Видео","body":"> Модуль 4 · Первый ролик\n\nОзвучка задаёт реальный темп ролика. Сначала согласуй текст, затем получи голос и только после этого уточняй тайминг сцен. Небольшая правка фразы может сдвинуть все последующие слова.\n\n## Текст для чтения\n\nПрочитай сценарий вслух. Сократи повторения, сложные вложенные фразы и перечисления, которые трудно различить на слух. Числа и сокращения запиши так, чтобы голос произнёс их ожидаемо. Не поручай синтезатору самостоятельно выбирать смысл неоднозначной даты.\n\nРаздели текст на смысловые фрагменты. Пометки о паузе и акценте должны соответствовать поддерживаемому формату выбранной модели. Неподдерживаемый тег может прозвучать как обычное слово.\n\n## Генерация\n\nВыбери голос с правами на использование, язык и доступные параметры. Для проверки сначала отправь короткий фрагмент с трудными словами. Послушай произношение и темп, затем генерируй остальное. В ElevenLabs и других сервисах стоимость и возможности зависят от модели и тарифа.\n\n## Приёмка\n\nПроверь каждый смысловой фрагмент, начало, конец и нежелательные паузы. Сравни фактическую длительность с планом. Ускорение дорожки может ухудшить разборчивость; сначала попробуй убрать лишнее из текста.\n\nСохрани финальный голос в public/audio и укажи его версию. Музыка и эффекты добавляются после того, как речь сама по себе понятна.\n\n## Задание\n\nОзвучь две версии одной короткой фразы и выбери подходящую по смыслу и разборчивости. Запиши параметры принятой версии.\n\n## Результат\n\nФинальная дорожка соответствует согласованному тексту и воспроизводится локально. Только она используется для последующих таймкодов.","position":15,"free_preview":false,"course_key":"ai-video","cover_url":null,"minutes":3,"xp":70,"copy_text":null,"quiz":[{"q":"Когда уточнять тайминг сцен?","options":["После выбора финальной озвучки","До написания текста","По приблизительной длине имени файла"],"correct":0,"explain":"После выбора финальной озвучки"}],"published":true,"kind":"lesson","emoji":"🎬","gradient":"aurora","video_url":null,"pinned":false},{"key":"course-16","source_type":"original_course_lesson","title":"Таймкоды и субтитры","subtitle":"Связываем слова с настоящей дорожкой","category":"Видео","body":"> Модуль 4 · Первый ролик\n\nТаймкод отмечает момент начала и конца фразы или слова в аудио. Он помогает синхронизировать подпись, изображение и движение. Длительность текста по числу букв не заменяет измерение реальной речи.\n\n## Подготовка данных\n\nИспользуй транскрипцию с временными метками или выравнивание текста по финальному голосу. Способ зависит от доступного инструмента. Сохрани результат как JSON: текст, start и end в секундах. Проверь единицы, порядок и совпадение текста с дорожкой.\n\nПример записи: text = «сначала», start = 0.4, end = 0.8. Это учебные числа; реальные значения получаются из твоего аудио.\n\n## Кадры\n\nДля позиции в видео умножай секунды на fps и используй согласованное округление. При 30 fps отметка 1,2 секунды соответствует 36-му кадру. Проверь, откуда считается время: от начала композиции или внутри сцены.\n\n## Субтитры\n\nГруппируй слова по смыслу и доступному месту, а не только по одинаковому числу символов. Две короткие строки часто читаются лучше длинной. Подпись не должна появляться задолго до фразы или исчезать до её завершения. Анимация подсветки добавляется после проверки статичного варианта.\n\n## Контроль\n\nПосмотри начало, середину и конец дорожки. Накопившийся сдвиг обычно говорит о неправильной версии аудио, единицах или расчёте времени. Исправляй причину до ручного перемещения всех титров.\n\n## Задание\n\nПодготовь таймкоды для десятисекундного фрагмента и проверь три слова вручную. Собери субтитры без эффектов.\n\n## Результат\n\nФразы совпадают со звуком, данные отсортированы, а титры помещаются в безопасной зоне телефона.","position":16,"free_preview":false,"course_key":"ai-video","cover_url":null,"minutes":3,"xp":70,"copy_text":null,"quiz":[{"q":"Как перевести 1,2 секунды в кадры при 30 fps?","options":["Умножить: получится 36 кадров","Разделить: получится 0,04 кадра","Использовать число букв в фразе"],"correct":0,"explain":"Умножить: получится 36 кадров"}],"published":true,"kind":"lesson","emoji":"🎬","gradient":"sunset","video_url":null,"pinned":false},{"key":"course-17","source_type":"original_course_lesson","title":"План и сборка первого ролика","subtitle":"Объединяем сцены, материалы и время","category":"Видео","body":"> Модуль 4 · Первый ролик\n\nПосле принятой озвучки сториборд превращается в точный план. У каждой сцены есть время начала, длительность, компонент, материалы и смысловая функция.\n\n## Сцены\n\nВ учебном выпуске первая сцена задаёт вопрос, вторая показывает сценарии использования, третья сравнивает критерии, четвёртая формулирует вывод. Сократи структуру, если текст не требует четырёх отдельных экранов.\n\nСохрани параметры в одном месте: fps, размер, общую длительность и интервалы. Длина композиции должна включать финальную речь и согласованный хвост. Пустой кадр в конце возникает, когда план и фактическая длительность расходятся.\n\n## Монтаж в Remotion\n\nSequence позволяет поставить участок на таймлайн. Внутри последовательности локальный frame считается относительно её начала — это важно для анимаций. Общая аудиодорожка и локальные эффекты должны использовать понятные временные основания. API сверяй в [документации Remotion](https://www.remotion.dev/docs/sequence).\n\nСначала собери статичные сцены с голосом. Затем добавь ограниченный набор движений. Проверка смысловой связи должна оставаться возможной без эффекта перехода.\n\n## Материалы\n\nУ каждого пути есть настоящий файл. Изображение имеет подходящее разрешение и правильное соотношение сторон. Замена материала не должна неожиданно изменить размер карточки.\n\n## Задание\n\nСобери все сцены в одном предпросмотре. Просмотри переходы и отметь, где кадр появляется раньше или позже нужной фразы.\n\n## Результат\n\nРолик целиком воспроизводится с принятой дорожкой; порядок, длительность и пути файлов согласованы. Правки вносятся в план и соответствующую сцену.","position":17,"free_preview":false,"course_key":"ai-video","cover_url":null,"minutes":3,"xp":70,"copy_text":null,"quiz":[{"q":"Что проверить у пути к изображению?","options":["Что файл существует и подходит для кадра","Только красивое название","Что путь встречается в промпте"],"correct":0,"explain":"Что файл существует и подходит для кадра"}],"published":true,"kind":"lesson","emoji":"🎬","gradient":"mint","video_url":null,"pinned":false},{"key":"course-18","source_type":"original_course_lesson","title":"Проверка и экспорт MP4","subtitle":"Принимаем результат после просмотра готового файла","category":"Видео","body":"> Модуль 4 · Первый ролик\n\nПредпросмотр помогает править ролик, а экспорт создаёт файл для публикации. Оба результата проверяются: успешный рендер не подтверждает содержание, читаемость и звук.\n\n## До экспорта\n\nПроверь общую длительность, начало и конец каждой сцены, наличие материалов и шрифтов. Посмотри длинные подписи и положение субтитров. Убедись, что композиция использует финальную голосовую дорожку.\n\nПрослушай речь на небольшой громкости. Музыка не должна закрывать слова; резкие скачки громкости и обрыв конца фразы исправляются до экспорта.\n\n## Параметры файла\n\nДля учебного вертикального ролика используем 1080×1920 и 30 fps. Выбранный формат, кодек и качество должны соответствовать способу публикации; актуальные требования площадки проверяются отдельно. Слишком большой файл может затруднить передачу, слишком сильное сжатие испортит мелкие детали.\n\n## После экспорта\n\nОткрой MP4 обычным плеером и на телефоне. Проверь изображение, звук, длительность и отсутствие пустого хвоста. Промотай конец: ошибка может быть только в последней секунде. Если файл отправляется через мессенджер со сжатием, проверь также полученный вариант.\n\nЗапиши команду и параметры экспорта в README. Сохрани итоговую версию отдельно от черновика и оставь рядом исходники.\n\n## Задание\n\nСоздай output/final-v1.mp4 и заполни чек-лист: формат, размер, fps, длительность, звук, титры, первые и последние кадры.\n\n## Результат\n\nГотовый файл воспроизводится и проверен целиком. Название однозначно указывает принятую версию, а проект позволяет повторить экспорт.","position":18,"free_preview":false,"course_key":"ai-video","cover_url":null,"minutes":3,"xp":70,"copy_text":null,"quiz":[{"q":"Когда экспорт можно считать принятым?","options":["После просмотра и проверки MP4","Сразу после появления файла","После сообщения агента «готово»"],"correct":0,"explain":"После просмотра и проверки MP4"}],"published":true,"kind":"lesson","emoji":"🎬","gradient":"ocean","video_url":null,"pinned":false},{"key":"course-19","source_type":"original_course_lesson","title":"Следующий выпуск и автоматизация","subtitle":"Ускоряем устойчивую часть процесса","category":"Видео","body":"> Модуль 5 · Следующие выпуски\n\nПосле первого ролика становится понятно, что действительно повторяется. Автоматизируй эти этапы, сохраняя проверки содержания и результата. Копирование незавершённого процесса обычно переносит ошибки в следующий выпуск.\n\n## Основа нового выпуска\n\nСохрани токены, компоненты и команды. Новый текст, голос и план должны лежать отдельно от прошлого выпуска. Удобно иметь манифест: идентификатор ролика, тема, материалы, текущий статус и принятый экспорт.\n\n## Что автоматизировать\n\nПроверку наличия файлов, подготовку таймкодов, создание базовой таблицы сцен, запуск рендера и сбор технической статистики. Генерация может возвращать ошибку; у шага должны быть предел повторов, лог и понятный статус.\n\nНе запускай платную генерацию заново только потому, что предыдущая сессия прервалась. Сохраняй идентификатор задачи и принятый результат. Повторный запуск должен использовать уже готовые материалы, когда это возможно.\n\n## Что проверяет человек\n\nФакты, актуальные цены, права на материалы, смысл сравнения, произношение и весь итоговый ролик. Автоматическая проверка переполнения не оценивает обещание в заголовке.\n\n## Разбор выпуска\n\nЗапиши стоимость, время подготовки и проверки, количество неудачных генераций и повторяющиеся проблемы. После публикации добавь данные по удержанию и нужному целевому действию. Для изменения процесса назови проблему, которую оно решает.\n\n## Задание\n\nСобери второй ролик на новой теме с теми же компонентами. Измерь, какой этап удалось ускорить без потери качества.\n\n## Результат\n\nДва выпуска имеют отдельные данные и воспроизводимую сборку. Автоматизированные шаги сообщают о сбоях, а решение о готовности опирается на проверку файла.","position":19,"free_preview":false,"course_key":"ai-video","cover_url":null,"minutes":3,"xp":70,"copy_text":null,"quiz":[{"q":"Когда полезно автоматизировать этап?","options":["Когда его вход, выход и проверка уже устойчивы","До понимания первого результата","Когда он скрывает ошибку предыдущего шага"],"correct":0,"explain":"Когда его вход, выход и проверка уже устойчивы"}],"published":true,"kind":"lesson","emoji":"🎬","gradient":"candy","video_url":null,"pinned":false},{"key":"course-20","source_type":"original_course_lesson","title":"Находим идею для блога","subtitle":"Начинаем с вопроса аудитории и проверяем гипотезу","category":"Видео","body":"> Модуль 6 · Идеи для блога\n\nИдея становится выпуском, когда понятно, кому она нужна и что человек узнает. Набор трендов помогает исследовать спрос, но не заменяет собственный опыт и проверку фактов.\n\n## Источники вопросов\n\nКомментарии, обращения клиентов, поисковые формулировки, повторяющиеся ошибки новичков и собственная практика. Записывай реальный вопрос и контекст человека. Тема «телефоны» широкая; вопрос «что выбрать, если снимаю детей в движении» задаёт конкретный сценарий.\n\n## Карточка идеи\n\nУкажи аудиторию, проблему, обещаемый результат, пример и факт, который нужно проверить. Добавь формат: сравнение, короткая инструкция, разбор ошибки или демонстрация. Не обещай результат, который ролик не сможет показать.\n\n## Отбор\n\nСравни идеи по полезности для аудитории, наличию материала, достоверности и возможности объяснить мысль коротко. Популярность темы полезна, но сама по себе не создаёт ценного выпуска. Лучше один проверенный пример, чем несколько непроверенных обещаний.\n\n## Небольшой тест\n\nПодготовь три варианта начала с одной и той же основной мыслью. Выбери тот, который понятно связывает вопрос и результат. После публикации оцени удержание и нужное действие зрителя, учитывая размер выборки. Один необычно удачный выпуск ещё не доказывает закономерность.\n\n## Задание\n\nСоставь пять карточек идей, выбери одну и напиши четырёхфразный сценарий: вопрос, объяснение, пример, вывод. Проверь каждый факт до передачи текста агенту.\n\n## Результат\n\nЕсть тема, понятная аудитории, проверяемое обещание и материал для первого сториборда. Идея готова к процессу из предыдущих модулей.","position":20,"free_preview":false,"course_key":"ai-video","cover_url":null,"minutes":3,"xp":70,"copy_text":null,"quiz":[{"q":"С чего начинать идею полезного ролика?","options":["С конкретного вопроса аудитории","С числа переходов","С покупки всех генераторов"],"correct":0,"explain":"С конкретного вопроса аудитории"}],"published":true,"kind":"lesson","emoji":"🎬","gradient":"lime","video_url":null,"pinned":false}]}$elaz_content$::jsonb;
  c jsonb;
  l jsonb;
  course_id_new bigint;
  lesson_id_new bigint;
  mapping jsonb := '{}'::jsonb;
  import_time timestamptz := now();
begin
  if exists(select 1 from public.settings where key='content_import:pronin-2026-10-v1') then
    raise notice 'Пакет уже импортирован';
    return;
  end if;
  c := p->'course';
  insert into public.courses(title,subtitle,description,emoji,gradient,price_stars,invite_unlock,position,published)
  values(c->>'title',c->>'subtitle',c->>'description',c->>'emoji',c->>'gradient',0,0,0,true)
  returning id into course_id_new;
  for l in select value from jsonb_array_elements(p->'lessons') loop
    insert into public.lessons(kind,title,subtitle,category,emoji,gradient,cover_url,body,video_url,copy_text,quiz,minutes,xp,pinned,published,published_at,course_id,position,free_preview)
    values('lesson',l->>'title',l->>'subtitle',l->>'category',l->>'emoji',l->>'gradient',l->>'cover_url',l->>'body',l->>'video_url',l->>'copy_text',l->'quiz',(l->>'minutes')::integer,(l->>'xp')::integer,false,(l->>'published')::boolean,
      case when (l->>'published')::boolean then import_time - coalesce((l->>'source_index')::integer,0)*interval '1 second' end,
      case when l->>'course_key' is not null then course_id_new else null end,(l->>'position')::integer,(l->>'free_preview')::boolean)
    returning id into lesson_id_new;
    mapping := mapping || jsonb_build_object(l->>'key',lesson_id_new);
  end loop;
  insert into public.settings(key,value)
  values('content_import:pronin-2026-10-v1',jsonb_build_object('date','2026-10-13','course_id',course_id_new,'lessons',mapping,'feed_count',64,'course_lesson_count',20,'authored_closed_lessons',19));
end;
$elaz_import$;
commit;
select value from public.settings where key='content_import:pronin-2026-10-v1';
